@tailwind base;
@tailwind components;
@tailwind utilities;

/* CRM campaigns light-mode redesign (overview + detail) */
.campaigns-overview-hero,
.campaigns-filter-panel,
.campaigns-table-card,
.campaigns-rail-card,
.campaign-detail-tabs,
.campaign-detail-kpi,
.campaign-detail-chart-card,
.campaign-detail-rail-card {
  border: 1px solid var(--crm-border);
  background: var(--crm-surface);
  color: var(--crm-text);
  box-shadow: var(--cinema-shadow-panel, var(--crm-shadow));
}

/* CRM Email ? metadata-first operations workspace (queue-shell aligned). */
.crm-email-workspace .crm-email-workspace-grid {
  width: 100%;
  min-width: 0;
}

.crm-email-workspace .crm-email-activity-card,
.crm-email-workspace .crm-email-quick-actions {
  border: 1px solid var(--crm-border);
  background: var(--crm-surface);
  box-shadow: var(--crm-shadow);
}

.crm-email-workspace .crm-email-activity-card,
.crm-email-workspace .crm-email-quick-actions {
  border-radius: 1.25rem;
}

.crm-email-workspace .crm-email-status-card {
  box-shadow: var(--crm-shadow);
}

.crm-email-workspace .crm-email-gmail-link-compact {
  white-space: nowrap;
}

.crm-email-workspace .crm-email-status-badge.crm-email-status-sent {
  border: 1px solid rgba(22, 163, 74, 0.28);
  background: rgba(22, 163, 74, 0.1);
}

.crm-email-workspace .crm-email-status-badge.crm-email-status-failed {
  border: 1px solid rgba(220, 38, 38, 0.28);
  background: rgba(220, 38, 38, 0.1);
}

.crm-email-workspace .crm-email-reply-row:hover,
.crm-email-workspace .crm-email-sent-row:hover {
  border-color: rgba(99, 102, 241, 0.22);
  background: rgba(239, 246, 255, 0.45);
}

.crm-email-workspace .crm-email-panel-scroll {
  overscroll-behavior: contain;
}

:root[data-theme="light"] .crm-queue-shell .crm-email-workspace .contacts-header-panel,
:root[data-theme="light"] .crm-queue-shell .crm-email-workspace .crm-queue-kpi-card,
:root[data-theme="light"] .crm-queue-shell .crm-email-workspace .crm-email-status-card,
:root[data-theme="light"] .crm-queue-shell .crm-email-workspace .crm-email-activity-card,
:root[data-theme="light"] .crm-queue-shell .crm-email-workspace .crm-email-quick-actions,
:root[data-theme="light"] .crm-queue-shell .crm-email-workspace .tasks-empty-state.crm-email-empty {
  border: 1px solid var(--crm-border) !important;
  border-radius: 1.25rem;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.99), rgba(248, 250, 252, 0.96)),
    radial-gradient(circle at 100% 0%, rgba(211, 229, 255, 0.44), transparent 35%) !important;
  box-shadow:
    0 1px 2px rgba(15, 23, 42, 0.04),
    0 16px 38px -30px rgba(15, 23, 42, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.95) !important;
  backdrop-filter: none;
}

:root[data-theme="light"] .crm-email-workspace .crm-queue-kpi-strip {
  gap: 0.75rem !important;
}

:root[data-theme="light"] .crm-email-workspace .crm-queue-kpi-card {
  min-height: 5.35rem !important;
  border-radius: 1.15rem !important;
  padding: 0.75rem 0.875rem !important;
}

:root[data-theme="light"] .crm-email-workspace .crm-queue-kpi-blue {
  background: linear-gradient(135deg, #ffffff 0%, #eef5ff 100%) !important;
}

:root[data-theme="light"] .crm-email-workspace .crm-queue-kpi-green {
  background: linear-gradient(135deg, #ffffff 0%, #e8faf2 100%) !important;
}

:root[data-theme="light"] .crm-email-workspace .crm-queue-kpi-violet {
  background: linear-gradient(135deg, #ffffff 0%, #f2edff 100%) !important;
}

:root[data-theme="light"] .crm-email-workspace .crm-queue-kpi-cyan {
  background: linear-gradient(135deg, #ffffff 0%, #e7f9fb 100%) !important;
}

@media (max-width: 1023px) {
  .crm-email-workspace .crm-email-workspace-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* CRM Email light mode ? scoped metadata-first operations workspace. */
.crm-email-workspace {
  background: var(--crm-bg);
}

.crm-email-panel,
.crm-email-kpi-card,
.crm-email-hero {
  transition:
    background 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease,
    transform 180ms ease,
    color 180ms ease;
}

.crm-email-card-glow {
  pointer-events: none;
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 62% 54% at 0% 0%, rgba(56, 189, 248, 0.08), transparent 58%),
    radial-gradient(ellipse 42% 38% at 100% 0%, rgba(124, 58, 237, 0.07), transparent 58%);
}

.crm-email-mail-illus {
  position: relative;
}

.crm-email-mail-spark {
  position: absolute;
  right: -0.15rem;
  top: -0.15rem;
}

@media (max-width: 640px) {
  .crm-email-hero-actions,
  .crm-email-hero-actions a,
  .crm-email-manage-btn,
  .crm-email-sync-cta {
    width: 100%;
  }

  .crm-email-sent-row {
    grid-template-columns: minmax(0, 1fr);
  }
}

:root[data-theme="light"] .crm-email-shell {
  --crm-email-page: #f8f2e9;
  --crm-email-page-2: #eef5ff;
  --crm-email-panel: rgba(255, 255, 255, 0.9);
  --crm-email-panel-2: rgba(255, 250, 243, 0.78);
  --crm-email-border: rgba(202, 189, 172, 0.54);
  --crm-email-border-strong: rgba(132, 153, 184, 0.34);
  --crm-email-text: #15233b;
  --crm-email-muted: #69778b;
  --crm-email-accent: #4f46e5;
  --crm-email-blue: #2563eb;
  --crm-email-violet: #7c3aed;
  --crm-email-success: #16a66a;
  --crm-email-danger: #dc4a5f;
  --crm-email-shadow: 0 24px 64px -36px rgba(40, 56, 87, 0.45), 0 10px 28px -20px rgba(74, 63, 53, 0.22);
  --crm-email-shadow-soft: 0 18px 48px -34px rgba(40, 56, 87, 0.38), 0 8px 20px -18px rgba(74, 63, 53, 0.2);
  background:
    radial-gradient(circle at 14% -10%, rgba(255, 181, 91, 0.2), transparent 31%),
    radial-gradient(circle at 76% -16%, rgba(91, 141, 255, 0.22), transparent 32%),
    linear-gradient(135deg, var(--crm-email-page) 0%, #f6f0e9 44%, var(--crm-email-page-2) 100%);
}

:root[data-theme="light"] .crm-email-shell .console-content {
  padding: 0;
  background:
    radial-gradient(circle at 11% 5%, rgba(255, 187, 104, 0.13), transparent 24%),
    radial-gradient(circle at 92% 4%, rgba(127, 105, 255, 0.12), transparent 28%),
    transparent;
}

:root[data-theme="light"] .crm-email-shell .console-nav {
  /* inherits standard console-nav background */
}

:root[data-theme="light"] .crm-email-shell .drawer-nav-link {
  border-radius: 16px;
  color: #62708a;
  font-weight: 650;
  letter-spacing: -0.01em;
}

:root[data-theme="light"] .crm-email-shell .drawer-nav-link:hover {
  background: rgba(255, 255, 255, 0.72);
  color: var(--crm-email-text);
  box-shadow: 0 10px 24px rgba(78, 73, 62, 0.08);
}

:root[data-theme="light"] .crm-email-shell .drawer-nav-link.active {
  color: #142846;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(238, 245, 255, 0.9)),
    radial-gradient(circle at 0% 50%, rgba(79, 70, 229, 0.12), transparent 44%);
  border-color: rgba(91, 141, 255, 0.22);
  box-shadow: 0 12px 28px -22px rgba(37, 99, 235, 0.5);
}

:root[data-theme="light"] .crm-email-shell .drawer-nav-link.active .drawer-nav-icon,
:root[data-theme="light"] .crm-email-shell .drawer-nav-link:hover .drawer-nav-icon {
  color: #1f6feb;
  background: rgba(226, 237, 255, 0.9);
}

:root[data-theme="light"] .crm-email-shell .topbar {
  /* inherits standard topbar background */
  backdrop-filter: blur(18px);
}

:root[data-theme="light"] .crm-email-shell .topbar-brand,
:root[data-theme="light"] .crm-email-shell .icon-btn,
:root[data-theme="light"] .crm-email-shell .profile-trigger {
  border-color: rgba(197, 181, 160, 0.56);
  background: rgba(255, 255, 255, 0.74);
  box-shadow: 0 10px 24px -20px rgba(42, 54, 76, 0.36);
}

:root[data-theme="light"] .crm-email-shell .topbar-center .global-search .input {
  height: 42px;
  border-color: rgba(197, 181, 160, 0.52);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  color: var(--crm-email-text);
  box-shadow: 0 14px 32px -26px rgba(37, 50, 74, 0.45);
}

:root[data-theme="light"] .crm-email-workspace {
  --crm-bg: transparent;
  --crm-surface: var(--crm-email-panel);
  --crm-surface-2: var(--crm-email-panel-2);
  --crm-border: var(--crm-email-border);
  --crm-text: var(--crm-email-text);
  --crm-text-muted: var(--crm-email-muted);
  --crm-accent: var(--crm-email-accent);
  --crm-success: var(--crm-email-success);
  --crm-danger: var(--crm-email-danger);
  color: var(--crm-email-text);
}

:root[data-theme="light"] .crm-email-inner {
  gap: 18px;
  padding-top: 22px;
  padding-bottom: 42px;
}

:root[data-theme="light"] .crm-email-hero,
:root[data-theme="light"] .crm-email-panel,
:root[data-theme="light"] .crm-email-kpi-card {
  border-color: var(--crm-email-border);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.9), rgba(255, 250, 243, 0.78)),
    radial-gradient(circle at 100% 0%, rgba(226, 237, 255, 0.52), transparent 34%);
  box-shadow: var(--crm-email-shadow-soft);
  backdrop-filter: blur(14px);
}

:root[data-theme="light"] .crm-email-panel:hover,
:root[data-theme="light"] .crm-email-kpi-card:hover {
  transform: translateY(-2px);
  border-color: var(--crm-email-border-strong);
  box-shadow: var(--crm-email-shadow);
}

:root[data-theme="light"] .crm-email-hero {
  border-radius: 24px;
}

:root[data-theme="light"] .crm-email-title {
  font-size: clamp(1.55rem, 2vw, 2rem);
  line-height: 1;
  letter-spacing: -0.045em;
  color: #17243a;
}

:root[data-theme="light"] .crm-email-subtitle {
  color: #6d788b;
}

:root[data-theme="light"] .crm-email-hero-icon {
  width: 52px;
  height: 52px;
  border: 0;
  border-radius: 18px;
  background: linear-gradient(135deg, #dbeafe, #ede9fe);
  color: #4f46e5;
  box-shadow: 0 16px 28px -20px rgba(79, 70, 229, 0.55);
}

:root[data-theme="light"] .crm-email-btn-primary,
:root[data-theme="light"] .crm-email-btn-secondary,
:root[data-theme="light"] .crm-email-manage-btn,
:root[data-theme="light"] .crm-email-sync-cta {
  min-height: 38px;
  border-radius: 14px;
  box-shadow: 0 10px 22px -18px rgba(37, 50, 74, 0.42);
}

:root[data-theme="light"] .crm-email-btn-primary,
:root[data-theme="light"] .crm-email-sync-cta {
  background: linear-gradient(135deg, #5b5cf6, #6d5dfc);
  color: #fff;
}

:root[data-theme="light"] .crm-email-btn-secondary,
:root[data-theme="light"] .crm-email-manage-btn {
  border-color: rgba(197, 181, 160, 0.52);
  background: rgba(255, 255, 255, 0.78);
  color: #253651;
}

:root[data-theme="light"] .crm-email-sender-card {
  border-radius: 26px;
}

:root[data-theme="light"] .crm-email-sender-compact {
  border-radius: 20px;
}

:root[data-theme="light"] .crm-email-section-label,
:root[data-theme="light"] .crm-email-kpi-label {
  color: #7a8494;
  letter-spacing: 0.075em;
}

:root[data-theme="light"] .crm-email-avatar {
  background: linear-gradient(135deg, #ede9fe, #dbeafe);
  color: #5b21b6;
  box-shadow: 0 14px 24px -18px rgba(91, 33, 182, 0.58);
}

:root[data-theme="light"] .crm-email-status-pill {
  background: rgba(255, 255, 255, 0.72);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.72);
}

:root[data-theme="light"] .crm-email-sender-metrics {
  border-top: 1px solid rgba(202, 189, 172, 0.38);
  padding-top: 14px;
}

:root[data-theme="light"] .crm-email-sender-aside {
  border-left: 1px solid rgba(202, 189, 172, 0.42);
  background:
    radial-gradient(circle at 85% 18%, rgba(124, 58, 237, 0.1), transparent 38%),
    rgba(255, 255, 255, 0.28);
}

:root[data-theme="light"] .crm-email-mail-illus {
  border: 0;
  background:
    radial-gradient(circle at 80% 6%, rgba(124, 58, 237, 0.2), transparent 26%),
    linear-gradient(135deg, #ede9fe, #dbeafe 72%, #f5f3ff);
  color: #5b5cf6;
  box-shadow: 0 18px 32px -20px rgba(79, 70, 229, 0.45);
}

:root[data-theme="light"] .crm-email-workspace-grid {
  align-items: stretch;
}

:root[data-theme="light"] .crm-email-replies-card,
:root[data-theme="light"] .crm-email-sent-card {
  border-radius: 24px;
}

:root[data-theme="light"] .crm-email-card-title-icon,
:root[data-theme="light"] .crm-email-empty-icon {
  border: 0;
  background: #ede9fe;
  color: #6d28d9;
  box-shadow: 0 12px 24px -18px rgba(109, 40, 217, 0.5);
}

:root[data-theme="light"] .crm-email-empty {
  background: transparent;
}

.crm-email-action-link,
.crm-email-view-all {
  border: 0;
  background: transparent;
  color: var(--crm-accent);
  cursor: pointer;
  font-family: inherit;
  padding: 0;
}

.crm-email-action-link:hover,
.crm-email-view-all:hover {
  color: var(--crm-accent-strong);
}

:root[data-theme="light"] .crm-email-action-link,
:root[data-theme="light"] .crm-email-view-all {
  color: #6d5dfc;
}

:root[data-theme="light"] .crm-email-reply-row,
:root[data-theme="light"] .crm-email-sent-row {
  border-color: rgba(209, 194, 174, 0.42);
}

:root[data-theme="light"] .crm-email-reply-row {
  background: rgba(255, 255, 255, 0.58);
}

:root[data-theme="light"] .crm-email-status-badge {
  border: 1px solid transparent;
  background: rgba(255, 255, 255, 0.62);
}

:root[data-theme="light"] .crm-email-status-sent {
  border-color: rgba(22, 166, 106, 0.22);
  background: rgba(209, 250, 229, 0.7);
}

:root[data-theme="light"] .crm-email-status-failed {
  border-color: rgba(220, 74, 95, 0.22);
  background: rgba(255, 228, 230, 0.76);
}

.crm-email-activity-panel {
  height: clamp(20rem, 42dvh, 28rem);
}

.crm-email-panel-scroll {
  overscroll-behavior: contain;
}

:root[data-theme="light"] .crm-email-dismiss-btn {
  border-color: rgba(202, 189, 172, 0.46);
  background: rgba(255, 255, 255, 0.66);
}

:root[data-theme="light"] .crm-email-kpi-card {
  border-radius: 24px;
  min-height: 6.375rem;
}

:root[data-theme="light"] .crm-email-kpi-card::before {
  content: "";
  position: absolute;
  inset: auto -22% -46% 34%;
  height: 90%;
  pointer-events: none;
  background: radial-gradient(circle, var(--email-kpi-glow), transparent 62%);
}

:root[data-theme="light"] .crm-email-kpi-icon {
  border: 0;
  background: var(--email-kpi-bg);
  color: var(--email-kpi-icon);
  box-shadow: 0 12px 24px -18px var(--email-kpi-shadow);
}

:root[data-theme="light"] .crm-email-kpi-value {
  font-size: clamp(1.65rem, 2.2vw, 1.875rem);
  letter-spacing: -0.055em;
  color: #17243a;
}

:root[data-theme="light"] .crm-email-kpi-blue {
  --email-kpi-icon: #1d4ed8;
  --email-kpi-bg: #dbeafe;
  --email-kpi-shadow: rgba(37, 99, 235, 0.18);
  --email-kpi-glow: rgba(55, 125, 255, 0.18);
}

:root[data-theme="light"] .crm-email-kpi-green {
  --email-kpi-icon: #059669;
  --email-kpi-bg: #d1fae5;
  --email-kpi-shadow: rgba(5, 150, 105, 0.15);
  --email-kpi-glow: rgba(16, 185, 129, 0.17);
}

:root[data-theme="light"] .crm-email-kpi-violet {
  --email-kpi-icon: #7c3aed;
  --email-kpi-bg: #ede9fe;
  --email-kpi-shadow: rgba(124, 58, 237, 0.18);
  --email-kpi-glow: rgba(139, 92, 246, 0.18);
}

:root[data-theme="light"] .crm-email-kpi-rose {
  --email-kpi-icon: #e11d48;
  --email-kpi-bg: #ffe4e6;
  --email-kpi-shadow: rgba(225, 29, 72, 0.14);
  --email-kpi-glow: rgba(244, 63, 94, 0.16);
}

@media (max-width: 1023px) {
  :root[data-theme="light"] .crm-email-sender-aside {
    border-left: 0;
    border-top: 1px solid rgba(202, 189, 172, 0.42);
  }
}

@media (max-width: 640px) {
  :root[data-theme="light"] .crm-email-inner {
    gap: 14px;
    padding-top: 18px;
  }

  :root[data-theme="light"] .crm-email-hero,
  :root[data-theme="light"] .crm-email-panel,
  :root[data-theme="light"] .crm-email-kpi-card {
    border-radius: 20px;
  }
}

.campaigns-overview-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  overflow: hidden;
  border-radius: 1.25rem;
  padding: 1rem;
  position: relative;
}

.campaigns-overview-hero::before,
.campaign-detail-chart-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 8% 0%, rgba(37, 99, 235, 0.12), transparent 34%),
    radial-gradient(circle at 98% 12%, rgba(139, 92, 246, 0.1), transparent 32%);
}

.campaigns-hero-copy {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: 0.625rem;
  position: relative;
  z-index: 1;
}

.campaigns-hero-icon,
.campaign-detail-kpi-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid color-mix(in srgb, var(--crm-accent) 30%, transparent);
  color: var(--crm-accent);
  background: color-mix(in srgb, var(--crm-accent) 12%, var(--crm-surface));
}

.campaigns-hero-icon {
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 0.75rem;
  background: linear-gradient(135deg, #dbeafe, #ede9fe);
  color: #2563eb;
  box-shadow: 0 12px 24px -18px rgba(37, 99, 235, 0.45);
}

.campaigns-eyebrow {
  margin: 0 0 0.1rem;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--crm-text-muted);
}

.campaigns-overview-hero h1 {
  margin: 0;
  font-size: clamp(1.25rem, 2vw, 1.5rem);
  line-height: 1.15;
  letter-spacing: -0.03em;
}

.campaigns-overview-hero p:not(.campaigns-eyebrow) {
  margin: 0.2rem 0 0;
  max-width: 42rem;
  color: var(--crm-text-muted);
  font-size: 0.8125rem;
}

.campaigns-hero-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 0.5rem;
  position: relative;
  z-index: 1;
}

.campaigns-hero-actions .campaigns-btn-primary,
.campaigns-hero-actions .campaigns-btn-secondary {
  min-height: 34px;
  border-radius: 999px;
  padding: 0.5rem 0.85rem;
  box-shadow: 0 10px 22px -18px rgba(37, 50, 74, 0.38);
}

.campaigns-page-shell .campaigns-hero-actions .campaigns-btn-primary {
  border: 1px solid rgba(79, 70, 229, 0.2);
  background: linear-gradient(135deg, #6d5dfc 0%, #377dff 100%);
  color: #ffffff;
  box-shadow: 0 14px 26px -18px rgba(55, 125, 255, 0.85);
}

.campaigns-page-shell .campaigns-hero-actions .campaigns-btn-primary:hover {
  background: linear-gradient(135deg, #5b4cf0 0%, #246df0 100%);
}

.campaigns-btn-primary,
.campaigns-btn-secondary,
.campaigns-filter-button,
.campaigns-row-actions a,
.campaigns-row-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border-radius: 0.9rem;
  font-weight: 700;
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease, background 180ms ease;
}

.campaigns-btn-primary {
  border: 1px solid transparent;
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  color: white;
  padding: 0.78rem 1rem;
  box-shadow: 0 16px 30px -18px rgba(37, 99, 235, 0.75);
}

.campaigns-btn-secondary,
.campaigns-filter-button {
  border: 1px solid var(--crm-border);
  background: var(--crm-surface-2);
  color: var(--crm-text);
  padding: 0.72rem 0.95rem;
}

.campaigns-btn-primary:hover,
.campaigns-btn-secondary:hover,
.campaigns-filter-button:hover,
.campaigns-kpi-card:hover,
