  color: var(--crm-text-muted);
  font-size: 0.58rem;
  font-weight: 850;
  letter-spacing: 0.06em;
  line-height: 1.15;
  text-transform: uppercase;
}

.campaign-detail-side-metric strong {
  display: block;
  margin-top: 0.45rem;
  color: var(--crm-text);
  font-size: 1.1rem;
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 1;
}

.campaign-detail-side-metric p {
  margin-top: 0.2rem;
  color: var(--crm-text-muted);
  font-size: 0.62rem;
  font-weight: 700;
  line-height: 1.2;
}

.campaign-detail-side-metric-track {
  margin-top: 0.45rem;
