}

.campaign-detail-side-queue-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: auto;
  border: 1px solid color-mix(in srgb, var(--crm-accent) 28%, var(--crm-border));
  border-radius: 0.85rem;
  background: color-mix(in srgb, var(--crm-accent) 9%, var(--crm-surface-2));
  color: var(--crm-accent);
  padding: 0.62rem 0.75rem;
  font-size: 0.78rem;
  font-weight: 850;
}

.campaign-detail-side-report {
  border: 1px solid rgba(136, 159, 190, 0.22);
  border-radius: 1rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.9), rgba(255, 255, 255, 0.74)),
    radial-gradient(circle at 0% 0%, rgba(55, 125, 255, 0.08), transparent 34%);
