}

.campaign-detail-side-report-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.65rem;
}

.campaign-detail-side-report-head p {
  color: var(--crm-text-muted);
  font-size: 0.64rem;
  font-weight: 900;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.campaign-detail-side-report-head span {
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.12);
  color: #059669;
  padding: 0.18rem 0.45rem;
  font-size: 0.58rem;
  font-weight: 900;
  text-transform: uppercase;
}

.campaign-detail-side-report-bars {
  display: flex;
  flex-direction: column;
  gap: 0.52rem;
}

.campaign-detail-side-report-row {
  --side-metric-accent: var(--crm-accent);
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.campaign-detail-side-report-row > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.campaign-detail-side-report-row span {
  color: var(--crm-text-muted);
  font-size: 0.68rem;
  font-weight: 800;
}

.campaign-detail-side-report-row strong {
  color: var(--crm-text);
  font-size: 0.78rem;
  font-weight: 900;
}

.campaign-detail-side-report-row p {
  color: var(--crm-text-muted);
  font-size: 0.63rem;
  font-weight: 720;
  line-height: 1.25;
}

.campaign-detail-side-signal-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
}

.campaign-detail-side-signal-grid > div {
  min-width: 0;
  border: 1px solid rgba(136, 159, 190, 0.2);
  border-radius: 0.9rem;
  background: rgba(255, 255, 255, 0.88);
  padding: 0.62rem;
}

.campaign-detail-side-signal-grid span {
  display: block;
  overflow: hidden;
  color: var(--crm-text-muted);
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.campaign-detail-side-signal-grid strong {
  display: block;
  margin-top: 0.28rem;
  color: var(--crm-text);
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: -0.04em;
}

.campaign-detail-side-signal-grid p {
  margin-top: 0.1rem;
  overflow: hidden;
  color: var(--crm-text-muted);
  font-size: 0.58rem;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.campaign-detail-side-breakdown,
.campaign-detail-side-focus {
  padding: 0.9rem;
}

.campaign-detail-side-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.campaign-detail-side-section-head p {
  color: var(--crm-text-muted);
  font-size: 0.66rem;
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.campaign-detail-side-section-head strong {
  color: var(--crm-text);
  font-size: 0.9rem;
  font-weight: 900;
  letter-spacing: -0.03em;
}

.campaign-detail-side-pipeline {
  display: flex;
  flex-direction: column;
  gap: 0.58rem;
}

.campaign-detail-side-pipeline-row {
  --side-metric-accent: var(--crm-accent);
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.campaign-detail-side-pipeline-row > div:first-child {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
}

.campaign-detail-side-pipeline-row span,
.campaign-detail-side-focus-list span {
  color: var(--crm-text-muted);
  font-size: 0.72rem;
  font-weight: 780;
}

.campaign-detail-side-pipeline-row strong,
.campaign-detail-side-focus-list strong {
  color: var(--crm-text);
  font-size: 0.86rem;
  font-weight: 900;
}

.campaign-detail-side-focus {
  flex: 1;
}

.campaign-detail-side-focus-list {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.65rem;
}

.campaign-detail-side-focus-list > div {
  border: 1px solid rgba(136, 159, 190, 0.22);
  border-radius: 0.95rem;
  background: rgba(255, 255, 255, 0.9);
  padding: 0.7rem;
}

.campaign-detail-side-focus-list p {
  margin-top: 0.18rem;
  color: var(--crm-text-muted);
  font-size: 0.68rem;
  font-weight: 650;
  line-height: 1.25;
}

.campaign-detail-rail-card {
  min-width: 0;
  overflow: hidden;
  border-radius: 1.2rem;
}

.campaign-detail-workbench > .campaign-detail-rail {
  position: sticky;
  top: 1rem;
  max-height: none;
  overflow: visible;
}

.campaign-detail-filter-row label > span {
  color: var(--crm-text-muted);
  font-size: 0.66rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.campaign-detail-contact-workspace {
  min-width: 0;
}

.campaign-detail-roster-shell {
  display: flex;
  min-height: 0;
  max-height: none;
  flex: 1 1 auto;
  flex-direction: column;
  scroll-behavior: smooth;
}

.campaign-detail-roster-sticky {
  position: relative;
  top: 0;
  z-index: 6;
  flex: 0 0 auto;
  border-bottom: 1px solid var(--cinema-border-subtle);
  background: color-mix(in srgb, var(--crm-surface) 94%, transparent);
  backdrop-filter: blur(14px);
}

.campaign-detail-filter-row {
  position: relative;
  top: auto;
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 0.55rem;
  padding-block: 0.65rem;
}

.campaign-detail-filter-row label {
  display: flex;
  min-width: 8.25rem;
  flex-direction: column;
  gap: 0.25rem;
}

.campaign-detail-filter-search {
  flex: 1 1 17rem;
}

.campaign-detail-filter-count {
  margin-left: auto;
  align-self: center;
  white-space: nowrap;
  color: var(--crm-text-muted);
  font-size: 0.72rem;
  font-weight: 750;
}

.campaign-detail-inline-toast {
  margin: 0 1rem 0.65rem;
  border: 1px solid color-mix(in srgb, var(--crm-success) 40%, transparent);
  border-radius: 0.9rem;
  background: color-mix(in srgb, var(--crm-success) 10%, transparent);
  color: var(--crm-success);
  padding: 0.55rem 0.75rem;
  font-size: 0.82rem;
  font-weight: 750;
}

.campaign-detail-bulk-bar {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin: 0 1rem 0.7rem;
  border: 1px solid color-mix(in srgb, var(--crm-accent) 30%, transparent);
  border-radius: 1rem;
  background: color-mix(in srgb, var(--crm-accent) 10%, transparent);
  padding: 0.55rem;
  box-shadow: var(--crm-shadow);
  flex-wrap: wrap;
}

.campaign-detail-bulk-assignee {
  flex: 1 1 18rem;
  min-width: min(100%, 18rem);
}

.campaign-detail-roster-scroll {
  min-height: 0;
  flex: 1 1 auto;
  overflow-y: auto;
  overscroll-behavior: contain;
  scroll-behavior: smooth;
  scrollbar-gutter: stable;
}

.campaign-detail-page > .campaign-detail-analytics {
  grid-template-columns: minmax(0, 1.12fr) minmax(18rem, 0.92fr) minmax(18rem, 0.92fr);
}

.campaign-detail-overview-grid {
  grid-template-columns: minmax(0, 1fr) minmax(18rem, 22rem);
}

.campaign-detail-main-flow,
.campaign-detail-analytics {
  min-width: 0;
}

.campaign-detail-analytics {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(18rem, 0.85fr) minmax(18rem, 0.9fr);
  gap: 1rem;
}

.campaign-detail-chart-card {
  position: relative;
  overflow: hidden;
  min-height: 16rem;
  border-radius: 1.4rem;
  padding: 1.05rem;
}

.campaign-detail-chart-card > * {
  position: relative;
  z-index: 1;
}

.campaign-detail-card-head span {
  border: 1px solid var(--crm-border);
  border-radius: 999px;
  color: var(--crm-text-muted);
  background: var(--crm-surface-2);
  padding: 0.28rem 0.55rem;
  font-size: 0.68rem;
  font-weight: 800;
}

.campaign-detail-line-chart {
  width: 100%;
  height: 10rem;
  margin-top: 1rem;
}

.campaign-detail-mini-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.6rem;
}

.campaign-detail-mini-stats span {
  border: 1px solid var(--crm-border);
  border-radius: 0.95rem;
  background: var(--crm-surface-2);
  color: var(--crm-text-muted);
  padding: 0.65rem;
  font-size: 0.74rem;
}

.campaign-detail-mini-stats strong {
  display: block;
  color: var(--crm-text);
  font-size: 1.1rem;
}

.campaign-detail-funnel {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 10.75rem;
  gap: 0.7rem;
  margin-top: 1rem;
}

.campaign-detail-funnel-row {
  display: grid;
  grid-template-columns: minmax(6rem, 1fr) 5.5rem 3rem 2.5rem;
  align-items: center;
  gap: 0.55rem;
}

.campaign-detail-funnel-row > div:first-child {
  height: 2.15rem;
  border-radius: 0.7rem;
  clip-path: polygon(0 0, 100% 0, 94% 100%, 0% 100%);
}

.campaign-detail-funnel-row span,
.campaign-detail-funnel-row small,
.campaign-detail-channel-row small {
  color: var(--crm-text-muted);
  font-size: 0.72rem;
  font-weight: 750;
}

.campaign-detail-funnel-row strong {
  color: var(--crm-text);
  font-size: 0.82rem;
}

.campaign-detail-channel-list {
  display: flex;
  flex-direction: column;
  gap: 0.62rem;
  margin-top: 1rem;
}

.campaign-detail-channel-row {
  display: grid;
  grid-template-columns: minmax(5.25rem, 0.92fr) minmax(4.5rem, 1fr) minmax(5.75rem, 0.88fr);
  align-items: center;
  gap: 0.55rem;
  min-width: 0;
  border: 1px solid color-mix(in srgb, var(--crm-border) 72%, transparent);
  border-radius: 0.95rem;
  background: color-mix(in srgb, var(--crm-surface-2) 62%, transparent);
  padding: 0.52rem;
}

.campaign-detail-channel-label {
  min-width: 0;
}

.campaign-detail-channel-label > span {
  display: inline-flex;
  height: 1.8rem;
  width: 1.8rem;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border-radius: 0.7rem;
  background: color-mix(in srgb, currentColor 12%, transparent);
}

.campaign-detail-channel-label strong {
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: 0.82rem;
}

.campaign-detail-channel-track {
  min-width: 0;
}

.campaign-detail-channel-metric {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.12rem;
  border-radius: 0.75rem;
  background: color-mix(in srgb, var(--crm-surface) 72%, transparent);
  padding: 0.38rem 0.45rem;
  text-align: center;
}

.campaign-detail-channel-metric strong {
  color: var(--crm-text);
  font-size: 0.82rem;
  font-weight: 900;
  line-height: 1;
}

.campaign-detail-channel-metric small {
  max-width: 100%;
  overflow-wrap: anywhere;
  line-height: 1.15;
}

.campaign-detail-workload-strip {
  display: flex;
  gap: 0.3rem;
  margin-top: 1rem;
}

.campaign-detail-workload-strip span {
  height: 0.42rem;
  border-radius: 999px;
  background: linear-gradient(90deg, #2563eb, #8b5cf6);
}

.campaign-detail-progress-ring {
  width: 7rem;
  height: 7rem;
  margin: 1rem auto;
  background: conic-gradient(#2563eb 0 var(--progress), color-mix(in srgb, var(--crm-border) 65%, transparent) var(--progress) 360deg);
}

.campaign-detail-progress-ring::before {
  content: "";
  position: absolute;
}

.campaign-detail-progress-ring span {
  display: grid;
  place-items: center;
  width: 4.9rem;
  height: 4.9rem;
  border-radius: 999px;
  background: var(--crm-surface);
  color: var(--crm-text);
  font-size: 1.4rem;
  font-weight: 900;
}

.campaign-detail-status-meta span,
.campaign-detail-owner-stack span {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  color: var(--crm-text-muted);
  font-size: 0.78rem;
  font-weight: 700;
}

.campaign-detail-note {
  color: var(--crm-text-muted);
  font-size: 0.85rem;
  line-height: 1.55;
}

.campaign-detail-owner-stack {
  margin-top: 0.85rem;
  border-top: 1px solid var(--crm-border);
  padding-top: 0.85rem;
}

.campaign-detail-owner-stack strong {
  color: var(--crm-text);
}

.campaign-detail-empty-chart {
  min-height: 8rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  border-radius: 1.25rem;
  border: 1px dashed color-mix(in srgb, var(--crm-border) 76%, transparent);
  color: var(--crm-muted);
  background: color-mix(in srgb, var(--crm-surface-2) 78%, transparent);
  text-align: center;
}

.campaign-detail-empty-chart strong {
  color: var(--crm-text);
}

.campaign-detail-empty-chart span {
  max-width: 24rem;
  font-size: 0.8125rem;
}

.campaign-detail-action-card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.campaign-detail-action-card {
  min-height: 6.25rem;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.35rem;
  border-radius: 1rem;
  border: 1px solid color-mix(in srgb, var(--crm-border) 82%, transparent);
  padding: 0.875rem;
  color: var(--crm-text);
  background: color-mix(in srgb, var(--crm-surface) 88%, transparent);
  text-align: left;
  transition: border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.campaign-detail-action-card span {
  display: inline-flex;
  height: 2rem;
  width: 2rem;
  align-items: center;
  justify-content: center;
  border-radius: 0.75rem;
  color: var(--crm-accent);
  background: color-mix(in srgb, var(--crm-accent) 12%, transparent);
}

.campaign-detail-action-card strong {
  font-size: 0.875rem;
}

.campaign-detail-action-card small {
  color: var(--crm-muted);
}

.campaign-detail-action-card:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--crm-accent) 35%, transparent);
  box-shadow: var(--crm-shadow);
  transform: translateY(-1px);
}

.campaign-detail-action-card:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.campaign-detail-activity-feed {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.campaign-detail-activity-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.65rem;
  font-size: 0.8125rem;
}

.campaign-detail-activity-dot {
  margin-top: 0.35rem;
  height: 0.6rem;
  width: 0.6rem;
  border-radius: 999px;
  box-shadow: 0 0 0 4px color-mix(in srgb, currentColor 13%, transparent);
}

.campaign-detail-activity-item strong {
  display: block;
  color: var(--crm-text);
}

.campaign-detail-activity-item p,
.campaign-detail-activity-item small {
  display: block;
  margin-top: 0.1rem;
  color: var(--crm-muted);
}

