:root[data-theme="light"] .campaigns-page-shell .campaigns-list-row .campaigns-row-icon.campaigns-status-paused,
:root[data-theme="light"] .campaigns-page-shell .campaigns-list-row .campaigns-row-icon.campaigns-status-scheduled {
