:root,
:root[data-theme="dark"] {
  --bg: #0c1218;
  --bg-soft: #101923;
  --panel: #141f2b;
  --panel-2: #1a2635;
  --text: #e1e9f1;
  --text-dim: #8ea0b2;
  --accent: #22a8ff;
  --accent-2: #4f7bff;
  --border: #26374a;
  --success: #34c27b;
  --warning: #f0b655;
  --danger: #ea6068;
  --info: #4ab2ff;
  --shadow: 0 8px 30px rgba(0, 0, 0, 0.24);

  /* CRM Phase 19A ? unified dark operational surfaces (Workspace-aligned) */
  --crm-bg: var(--bg-soft);
  --crm-surface: var(--panel);
  --crm-surface-2: var(--panel-2);
  --crm-border: var(--border);
  --crm-text: var(--text);
  --crm-text-muted: var(--text-dim);
  --crm-accent: var(--accent);
  --crm-accent-soft: color-mix(in srgb, var(--accent) 16%, transparent);
  --crm-danger: var(--danger);
  --crm-warning: var(--warning);
  --crm-success: var(--success);
  --crm-radius: 0.75rem;
  --crm-radius-lg: 1rem;
  --crm-shadow: 0 1px 2px rgba(0, 0, 0, 0.28);
  --crm-section-gap: 1rem;
}

.crm-page-shell {
  width: 100%;
}

/* CRM campaign routes ? theme-aware cinema workspace (19E.6) */
.crm-campaign-workspace input:not([type="checkbox"]):not([type="radio"]),
.crm-campaign-workspace textarea,
.crm-campaign-workspace select {
  background-color: var(--crm-surface-2) !important;
  border-color: var(--crm-border) !important;
  color: var(--crm-text) !important;
  box-shadow: none !important;
}
.crm-campaign-workspace input::placeholder,
.crm-campaign-workspace textarea::placeholder {
  color: var(--crm-text-muted) !important;
}
.crm-campaign-workspace select option {
  background: var(--crm-surface) !important;
  color: var(--crm-text) !important;
}

/* Phase 19E.3 ? subtle live campaign motion (respect reduced-motion) */
@keyframes crm-campaign-strip-pulse {
  0%,
  100% {
    opacity: 0.88;
  }
  50% {
    opacity: 1;
  }
}
@keyframes crm-campaign-live-dot {
  0%,
  100% {
    opacity: 0.5;
    transform: scale(0.9);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}
.crm-campaign-workspace .crm-campaign-status-strip-live {
  animation: crm-campaign-strip-pulse 2.8s ease-in-out infinite;
}
.crm-campaign-workspace .crm-campaign-live-dot {
  animation: crm-campaign-live-dot 2.4s ease-in-out infinite;
}
@media (prefers-reduced-motion: reduce) {
  .crm-campaign-workspace .crm-campaign-status-strip-live,
  .crm-campaign-workspace .crm-campaign-live-dot {
    animation: none;
  }
}

.crm-campaign-workspace button:disabled,
.crm-campaign-workspace a[aria-disabled="true"] {
  opacity: 1 !important;
}

/* Phase 19E.4 ? campaign command-center depth */
.crm-campaign-command-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 90% 70% at 10% -30%, rgba(56, 189, 248, 0.14), transparent 55%),
    radial-gradient(ellipse 60% 50% at 95% 20%, rgba(79, 123, 255, 0.08), transparent 50%),
    linear-gradient(180deg, rgba(26, 38, 53, 0.55) 0%, transparent 42%);
  pointer-events: none;
}
.crm-campaign-index-row-active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: linear-gradient(180deg, rgba(56, 189, 248, 0.95), rgba(56, 189, 248, 0.35));
  border-radius: 0.75rem 0 0 0.75rem;
}
.crm-campaign-performance-surface {
  background:
    radial-gradient(ellipse 80% 60% at 50% 0%, rgba(56, 189, 248, 0.06), transparent 55%),
    var(--crm-surface);
}
.crm-campaign-quick-strip {
  background: linear-gradient(180deg, rgba(26, 38, 53, 0.92) 0%, rgba(20, 31, 43, 0.96) 100%);
}
@media (prefers-reduced-motion: reduce) {
  .crm-campaign-index-row {
    transition: border-color 0.15s ease;
  }
  .crm-campaign-index-row:hover {
    transform: none;
  }
}

/* Phase 19E.5/19E.6 ? campaign cinema: dark mockup + light frosted SaaS */
:root[data-theme="dark"] .crm-campaign-cinema,
:root:not([data-theme="light"]) .crm-campaign-cinema {
  color-scheme: dark;
  --cinema-text: #f0f4f9;
  --cinema-text-muted: #8b9cb3;
  --cinema-text-dim: #6d7f99;
  --cinema-accent-blue: #60a5fa;
  --cinema-surface: #121a28;
  --cinema-surface-2: #161f2e;
  --cinema-surface-soft: #1a2438;
  --cinema-surface-hero: rgba(18, 26, 40, 0.92);
  --cinema-border: rgba(255, 255, 255, 0.08);
  --cinema-border-subtle: rgba(255, 255, 255, 0.06);
  --cinema-shadow-hero: 0 24px 80px -24px rgba(0, 0, 0, 0.75), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  --cinema-shadow-panel: 0 16px 48px -20px rgba(0, 0, 0, 0.7);
  --cinema-shadow-kpi: 0 12px 40px -16px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  --cinema-ring-track: rgba(255, 255, 255, 0.08);
  --cinema-gauge-glow: rgba(251, 191, 36, 0.25);
  --crm-surface: #121a28;
  --crm-surface-2: #161f2e;
  --crm-text: #f0f4f9;
  --crm-text-muted: #8b9cb3;
  --crm-border: #2a3a52;
  --crm-accent: #3b82f6;
  --crm-success: #34d399;
  --crm-warning: #fbbf24;
  --crm-danger: #f87171;
}

:root[data-theme="light"] .crm-campaign-cinema {
  color-scheme: light;
  --cinema-text: #0f172a;
  --cinema-text-muted: #64748b;
  --cinema-text-dim: #94a3b8;
  --cinema-accent-blue: #0284c7;
