  box-shadow: var(--cinema-shadow-panel);
}
.group\/menu:hover .crm-cinema-overflow-menu,
.group\/menu:focus-within .crm-cinema-overflow-menu {
  display: flex;
}
.crm-cinema-overflow-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  text-align: left;
  font-size: 0.75rem;
  color: var(--cinema-text-muted);
  transition: background 0.15s ease, color 0.15s ease;
}
.crm-cinema-overflow-item:hover {
  background: color-mix(in srgb, var(--cinema-surface-2) 80%, transparent);
  color: var(--cinema-text);
}
.crm-cinema-overflow-item-warn { color: #fcd34d; }
.crm-cinema-overflow-item-warn:hover { color: #fcd34d; }
.crm-cinema-overflow-item-danger:hover { color: #f87171; }
