:root[data-theme="light"] .crm-cinema-overflow-menu {
  background: #fff;
  box-shadow: 0 12px 32px -8px rgba(15, 23, 42, 0.12);
}

@media (prefers-reduced-motion: reduce) {
  .crm-cinema-row-active::after {
    box-shadow: 0 0 0 1px rgba(52, 211, 153, 0.2);
  }
}

