  border-radius: 9999px;
  filter: blur(60px);
  pointer-events: none;
}

@keyframes checklist-live-dot {
  0%,
  100% {
    opacity: 0.45;
    box-shadow: 0 0 0 0 rgba(52, 211, 153, 0);
  }
  50% {
    opacity: 1;
    box-shadow: 0 0 10px 2px rgba(52, 211, 153, 0.4);
  }
}
.crm-checklist-workspace .checklist-live-dot {
  animation: checklist-live-dot 2.6s ease-in-out infinite;
}

@keyframes checklist-orb-pulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.3;
  }
  50% {
    transform: scale(1.14);
    opacity: 0.55;
  }
}
.crm-checklist-workspace .checklist-orb-pulse {
  animation: checklist-orb-pulse 3.6s ease-in-out infinite;
}

@keyframes checklist-orb-ring {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.5;
  }
  50% {
    transform: scale(1.03);
    opacity: 0.75;
  }
}
.crm-checklist-workspace .checklist-orb-ring {
  animation: checklist-orb-ring 4.5s ease-in-out infinite;
}

@keyframes checklist-hero-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}
.crm-checklist-workspace .checklist-hero-orb {
  animation: checklist-hero-float 5s ease-in-out infinite;
}

@keyframes checklist-particle-drift {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
    opacity: 0.15;
  }
  33% {
    transform: translate(4px, -8px) scale(1.2);
    opacity: 0.45;
  }
  66% {
    transform: translate(-3px, 4px) scale(0.9);
    opacity: 0.25;
  }
}
.crm-checklist-workspace .checklist-particle {
  position: absolute;
  border-radius: 9999px;
  background: rgba(56, 189, 248, 0.7);
  box-shadow: 0 0 8px 1px rgba(56, 189, 248, 0.35);
  animation: checklist-particle-drift 7s ease-in-out infinite;
  pointer-events: none;
}

.crm-checklist-workspace .checklist-cinematic-hero {
  background:
    linear-gradient(165deg, rgba(26, 42, 66, 0.95) 0%, rgba(14, 22, 40, 0.98) 42%, rgba(6, 10, 20, 1) 100%);
}
:root[data-theme="light"] .crm-checklist-workspace .checklist-cinematic-hero {
  background: linear-gradient(
    165deg,
    rgba(255, 255, 255, 0.98) 0%,
    rgba(248, 250, 252, 0.96) 42%,
    rgba(241, 245, 249, 0.94) 100%
  );
}

.crm-checklist-workspace .checklist-panel-cinematic::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 0 80px -40px rgba(56, 189, 248, 0.12);
}

.crm-checklist-workspace .checklist-template-card {
  transition:
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.3s ease,
    box-shadow 0.35s ease;
}
.crm-checklist-workspace .checklist-template-card:hover {
  transform: translateY(-3px) scale(1.01);
}
.crm-checklist-workspace .checklist-template-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  opacity: 0.5;
  pointer-events: none;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.06) 0%,
    transparent 42%,
    transparent 100%
  );
}

.crm-checklist-workspace .checklist-feature-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(56, 189, 248, 0.25), transparent);
  opacity: 0;
  transition: opacity 0.3s ease;
}
.crm-checklist-workspace .checklist-feature-card:hover::before {
  opacity: 1;
}

.crm-checklist-workspace .checklist-side-panel {
  transition:
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}

@media (prefers-reduced-motion: reduce) {
  .crm-checklist-workspace .checklist-live-dot,
  .crm-checklist-workspace .checklist-orb-pulse,
  .crm-checklist-workspace .checklist-orb-ring,
