    grid-template-columns: minmax(0, 1fr) 21rem;
    grid-template-rows: auto auto auto;
    align-items: stretch;
  }

  .crm-wallboard-content-grid > :not(.crm-wallboard-panel-slot) {
    grid-column: 1;
  }

  .crm-wallboard-panel-slot {
    grid-column: 2;
    grid-row: 1 / -1;
    display: flex;
    min-height: 0;
    height: 100%;
    max-height: 100%;
    overflow: hidden;
  }
}

@media (min-width: 1536px) {
  .crm-wallboard-content-grid {
    grid-template-columns: minmax(0, 1fr) 22rem;
