  font-size: 12px; color: var(--console-muted); margin: 4px 0 0;
}
.dash-hero-status-pill {
  display: inline-flex; align-items: center; gap: 8px;
  color: color-mix(in srgb, var(--dash-internal) 82%, white 18%);
  background: color-mix(in srgb, var(--dash-internal) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--dash-internal) 24%, var(--dash-card-border));
  border-radius: 999px;
  padding: 7px 11px;
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.dash-hero-plot { overflow: hidden; min-height: 300px; }
.dash-hero-svg  { display: block; width: 100%; cursor: crosshair; color: var(--console-text); }

/* SVG chart animations */
.hg-area {
  --hg-area-opacity: 0.46;
  opacity: var(--hg-area-opacity);
  transition: opacity 180ms ease, filter 180ms ease;
  animation: hg-area-in 0.9s ease-out both;
  mix-blend-mode: screen;
}
.hg-area--incoming { --hg-area-opacity: 0.54; }
.hg-area--outgoing { --hg-area-opacity: 0.48; }
.hg-area--internal { --hg-area-opacity: 0.44; }
.hg-area--missed { --hg-area-opacity: 0.50; }
.hg-area.is-dimmed { opacity: 0.24; }
.hg-area.is-active {
  opacity: 0.68;
  filter: drop-shadow(0 18px 26px color-mix(in srgb, currentColor 20%, transparent));
}
@keyframes hg-area-in {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: var(--hg-area-opacity); transform: translateY(0); }
}
@keyframes spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
.hg-line {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: opacity 0.18s ease, stroke-width 0.18s ease, filter 0.18s ease;
  animation: hg-line-draw 1.15s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  filter: drop-shadow(0 0 8px color-mix(in srgb, currentColor 34%, transparent));
}
.hg-line--glow { opacity: 0.22; animation-delay: 0.08s; }
.hg-line.is-dimmed { opacity: 0.32; }
.hg-line.is-active:not(.hg-line--glow) {
  opacity: 1;
  stroke-width: 3.4px;
}
.hg-line.is-active.hg-line--glow { opacity: 0.42; }
@keyframes hg-line-draw {
  to { stroke-dashoffset: 0; }
}
.hg-clip-rect {
  animation: hg-clip-grow 1.3s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}
@keyframes hg-clip-grow {
  from { width: 0 !important; }
}
.hg-grid-line {
  stroke: currentColor;
  stroke-opacity: 0.055;
  stroke-width: 1;
}
.hg-baseline {
  stroke: currentColor;
  stroke-opacity: 0.13;
  stroke-width: 1;
}
.hg-axis-label {
  fill: currentColor;
  fill-opacity: 0.38;
  font-size: 11px;
  font-family: var(--font-mono, monospace);
}
.hg-axis-label--x { fill-opacity: 0.48; }
.hg-hover-line {
  stroke: color-mix(in srgb, var(--dash-outgoing) 44%, var(--console-muted));
  stroke-opacity: 0.48;
  stroke-width: 1;
  stroke-dasharray: 4 4;
  filter: drop-shadow(0 0 8px color-mix(in srgb, var(--dash-outgoing) 24%, transparent));
}
.hg-hover-pulse {
  opacity: 0.16;
  animation: hg-point-pulse 1.4s ease-in-out infinite;
  transform-box: fill-box;
  transform-origin: center;
}
.hg-hover-dot {
  fill: #e0f7ff;
  stroke-width: 3;
  filter: drop-shadow(0 0 8px rgba(255, 255, 255, 0.26));
}
@keyframes hg-point-pulse {
  0%, 100% { transform: scale(0.9); opacity: 0.14; }
  50% { transform: scale(1.45); opacity: 0.25; }
}
.hg-tooltip-bg {
  fill: color-mix(in srgb, var(--console-panel) 82%, transparent);
  stroke: color-mix(in srgb, var(--dash-internal) 30%, var(--console-border));
  stroke-width: 1;
  filter: drop-shadow(0 16px 30px rgba(0, 0, 0, 0.28));
  backdrop-filter: blur(14px);
}
.hg-tooltip-title {
  fill: var(--console-muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.03em;
  font-family: var(--font-mono, monospace);
}
.hg-tooltip-total {
  fill: var(--console-text);
  font-size: 14px;
  font-weight: 800;
  font-family: var(--font-sans, sans-serif);
}
.hg-tooltip-label {
  fill: var(--console-muted);
  font-size: 11px;
  font-family: var(--font-sans, sans-serif);
}
.hg-tooltip-value {
  fill: var(--console-text);
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  font-family: var(--font-mono, monospace);
}
.dash-chart-empty {
  display: flex; flex-direction: column; align-items: center;
  justify-content: center; min-height: 300px; padding: 48px 0; gap: 8px;
  background:
    radial-gradient(circle at center, color-mix(in srgb, var(--dash-total-line, #38bdf8) 9%, transparent) 0%, transparent 42%);
  border: 1px dashed color-mix(in srgb, var(--dash-card-border) 70%, transparent);
  border-radius: 16px;
}
.dash-chart-empty-orb {
  display: grid; place-items: center;
  width: 50px; height: 50px;
  color: var(--dash-total-line, #38bdf8);
  background: color-mix(in srgb, var(--dash-total-line, #38bdf8) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--dash-total-line, #38bdf8) 22%, var(--dash-card-border));
  border-radius: 999px;
}
.dash-chart-empty-text { font-size: 15px; font-weight: 600; color: var(--console-muted); margin: 0; }
.dash-chart-empty-sub  { font-size: 13px; color: var(--console-muted); opacity: 0.65; margin: 0; }

@media (max-width: 720px) {
  .dash-hero-card { padding: 18px 16px 16px; }
  .dash-hero-header { gap: 10px; margin-bottom: 12px; }
  .dash-hero-status-pill { width: fit-content; }
  .dash-hero-plot,
  .dash-chart-empty { min-height: 240px; }
  .dash-hero-svg { height: 240px; }
}

/* ?? KPI card row ??????????????????????????????????????????????????????? */
.dash-kpi-row {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
  gap: 14px;
}
.dash-kpi2 {
  position: relative;
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  box-shadow: var(--dash-shadow);
  overflow: hidden;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
  animation: kpi2-enter 0.45s ease-out both;
  animation-delay: var(--kpi-delay, 0ms);
}
.dash-kpi2:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.12);
}
@keyframes kpi2-enter {
  from { opacity: 0; transform: translateY(14px); }
  to   { opacity: 1; transform: translateY(0);    }
}
/* Colored top accent bar */
.dash-kpi2-accent {
  height: 4px; width: 100%; position: absolute; top: 0; left: 0;
}
.dash-kpi2--active   .dash-kpi2-accent { background: var(--console-accent); }
.dash-kpi2--incoming .dash-kpi2-accent { background: var(--dash-incoming); }
.dash-kpi2--outgoing .dash-kpi2-accent { background: var(--dash-outgoing); }
.dash-kpi2--internal .dash-kpi2-accent { background: var(--dash-internal); }
.dash-kpi2--missed   .dash-kpi2-accent { background: var(--dash-missed);   }
.dash-kpi2--default  .dash-kpi2-accent { background: var(--dash-card-border); }
/* Pulse on active calls card */
.dash-kpi2--active {
  animation: kpi2-enter 0.45s ease-out both, dash-pulse-kpi 3s ease-in-out 0.6s infinite;
}
@keyframes dash-pulse-kpi {
  0%, 100% { box-shadow: var(--dash-shadow); }
  50%       { box-shadow: 0 0 0 3px rgba(43, 165, 255, 0.15), var(--dash-shadow); }
}
.dash-kpi2-body { padding: 20px 20px 18px; padding-top: 22px; }
.dash-kpi2-label {
  font-size: 11px; font-weight: 700; color: var(--console-muted);
  text-transform: uppercase; letter-spacing: 0.07em;
}
.dash-kpi2-value {
  font-size: 36px; font-weight: 800; line-height: 1.05;
  letter-spacing: -0.04em; margin-top: 10px;
  font-variant-numeric: tabular-nums;
}
.dash-kpi2-meta {
  font-size: 11px; color: var(--console-muted); margin-top: 6px; line-height: 1.4;
}

/* ?? Supporting cards ??????????????????????????????????????????????????? */
.dash-support-row {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 14px;
}
.dash-support-card {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  padding: 22px 24px;
  box-shadow: var(--dash-shadow);
  animation: dash-card-in 0.5s ease-out 0.35s both;
}
.dash-support-header { margin-bottom: 18px; }
.dash-support-title  { font-size: 14px; font-weight: 700; margin: 0 0 3px; color: var(--console-text); }
.dash-support-sub    { font-size: 12px; color: var(--console-muted); margin: 0; }
.dash-support-empty  { font-size: 13px; color: var(--console-muted); padding: 16px 0; margin: 0; }

/* Donut layout */
.dash-donut-layout {
  display: flex; align-items: center; gap: 24px;
}
.dash-donut-svg { flex-shrink: 0; }
.dash-donut-arc {
  transition: opacity 0.2s ease;
}
.dash-donut-arc:hover { opacity: 1 !important; filter: brightness(1.1); }
.dash-donut-legend {
  display: flex; flex-direction: column; gap: 10px; flex: 1;
}
.dash-donut-legend-row {
  display: flex; align-items: center; gap: 8px; font-size: 13px;
}
.dash-donut-swatch {
  width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0;
}
.dash-donut-legend-label { color: var(--console-muted); flex: 1; }
.dash-donut-legend-val   { font-weight: 700; font-variant-numeric: tabular-nums; }
.dash-donut-legend-pct   { font-size: 11px; color: var(--console-muted); min-width: 32px; text-align: right; }

/* Answer rate ring */
.dash-rate-ring-wrap { position: relative; flex-shrink: 0; }
.dash-rate-center {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
}
.dash-rate-pct {
  font-size: 20px; font-weight: 800; letter-spacing: -0.04em;
  font-variant-numeric: tabular-nums;
}
.dash-rate-tagline {
  font-size: 11px; font-weight: 600;
  color: var(--console-muted); margin-top: 6px;
  padding-top: 10px; border-top: 1px solid var(--dash-card-border);
}

/* ?? Live calls panel ??????????????????????????????????????????????????? */
.dash-live-panel {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  padding: 20px;
  box-shadow: var(--dash-shadow);
}
/* Improved live calls empty state */
.dash-live-empty {
  display: flex; flex-direction: column; align-items: center;
  justify-content: center; padding: 40px 20px; gap: 10px; text-align: center;
}
.dash-live-empty-ring {
  width: 56px; height: 56px; border-radius: 50%;
  background: color-mix(in srgb, var(--console-success) 10%, var(--dash-card));
  border: 2px solid color-mix(in srgb, var(--console-success) 30%, transparent);
  display: flex; align-items: center; justify-content: center;
  animation: dash-ring-pulse 2.5s ease-in-out infinite;
}
.dash-live-empty-icon { color: var(--console-success); opacity: 0.8; }
@keyframes dash-ring-pulse {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--console-success) 20%, transparent); }
  50%       { box-shadow: 0 0 0 10px transparent; }
}
.dash-live-empty-title { font-size: 15px; font-weight: 700; margin: 0; }
.dash-live-empty-sub   { font-size: 13px; color: var(--console-muted); margin: 0; max-width: 300px; }

/* ?? Shared card entrance animation ???????????????????????????????????? */
@keyframes dash-card-in {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ?? Insight row grid ??????????????????????????????????????????????????? */
.dash-insights-row {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 14px;
}
@media (max-width: 900px) {
  .dash-insights-row { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 580px) {
  .dash-insights-row { grid-template-columns: 1fr; }
}

/* ?? Smart Insight Card ????????????????????????????????????????????????? */
.dash-insight-card {
  position: relative;
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  padding: 24px;
  box-shadow: var(--dash-shadow);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 10px;
  animation: dash-card-in 0.5s ease-out 0.45s both;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.dash-insight-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.12);
}
/* Decorative background gradient blob */
.dash-insight-bg {
  position: absolute; top: -40px; right: -40px;
  width: 160px; height: 160px; border-radius: 50%;
  pointer-events: none;
}
.dash-insight-card--green  .dash-insight-bg { background: radial-gradient(circle, color-mix(in srgb, var(--dash-incoming) 18%, transparent) 0%, transparent 70%); }
.dash-insight-card--blue   .dash-insight-bg { background: radial-gradient(circle, color-mix(in srgb, var(--console-accent) 18%, transparent) 0%, transparent 70%); }
.dash-insight-card--amber  .dash-insight-bg { background: radial-gradient(circle, rgba(251, 191, 36, 0.18) 0%, transparent 70%); }
.dash-insight-card--red    .dash-insight-bg { background: radial-gradient(circle, color-mix(in srgb, var(--dash-missed) 18%, transparent) 0%, transparent 70%); }
.dash-insight-card--purple .dash-insight-bg { background: radial-gradient(circle, color-mix(in srgb, var(--dash-internal) 18%, transparent) 0%, transparent 70%); }
/* Accent border-top */
.dash-insight-card--green  { border-top: 3px solid var(--dash-incoming); }
.dash-insight-card--blue   { border-top: 3px solid var(--console-accent); }
.dash-insight-card--amber  { border-top: 3px solid #f59e0b; }
.dash-insight-card--red    { border-top: 3px solid var(--dash-missed); }
.dash-insight-card--purple { border-top: 3px solid var(--dash-internal); }
/* Icon wrap */
.dash-insight-icon-wrap {
  width: 36px; height: 36px; border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.dash-insight-card--green  .dash-insight-icon-wrap { background: color-mix(in srgb, var(--dash-incoming) 16%, var(--dash-card)); color: var(--dash-incoming); }
.dash-insight-card--blue   .dash-insight-icon-wrap { background: color-mix(in srgb, var(--console-accent) 16%, var(--dash-card)); color: var(--console-accent); }
.dash-insight-card--amber  .dash-insight-icon-wrap { background: rgba(251,191,36,0.14); color: #f59e0b; }
.dash-insight-card--red    .dash-insight-icon-wrap { background: color-mix(in srgb, var(--dash-missed) 16%, var(--dash-card)); color: var(--dash-missed); }
.dash-insight-card--purple .dash-insight-icon-wrap { background: color-mix(in srgb, var(--dash-internal) 16%, var(--dash-card)); color: var(--dash-internal); }
/* Big stat */
.dash-insight-big-stat {
  display: flex; align-items: baseline; gap: 6px; margin-top: 4px;
}
.dash-insight-big-num {
  font-size: 42px; font-weight: 800; line-height: 1;
  letter-spacing: -0.05em; font-variant-numeric: tabular-nums;
}
.dash-insight-big-label {
  font-size: 13px; font-weight: 500; color: var(--console-muted); align-self: flex-end; padding-bottom: 4px;
}
.dash-insight-headline {
  font-size: 15px; font-weight: 700; margin: 0; line-height: 1.3; color: var(--console-text);
}
.dash-insight-body {
  font-size: 12px; color: var(--console-muted); margin: 0; line-height: 1.6;
}
/* Empty / loading states */
.dash-insight-card--loading { min-height: 140px; justify-content: center; }
.dash-insight-card--empty   { min-height: 140px; justify-content: center; align-items: center; text-align: center; }
.dash-insight-empty-icon    { color: var(--console-muted); opacity: 0.4; margin-bottom: 8px; }

/* ?? Call Outcomes Card ????????????????????????????????????????????????? */
.dash-outcomes-card, .dash-snapshot-card {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  padding: 22px 24px;
  box-shadow: var(--dash-shadow);
  animation: dash-card-in 0.5s ease-out 0.5s both;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.dash-outcomes-card:hover, .dash-snapshot-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.10);
}
.dash-outcomes-header {
  display: flex; align-items: baseline; justify-content: space-between;
  margin-bottom: 16px;
}
.dash-outcomes-title { font-size: 14px; font-weight: 700; margin: 0; color: var(--console-text); }
.dash-outcomes-sub   { font-size: 11px; color: var(--console-muted); }

/* Stacked bar */
.dash-stacked-bar {
  display: flex; height: 10px; border-radius: 99px;
  overflow: hidden; gap: 2px; margin-bottom: 18px;
}
.dash-stacked-seg {
  border-radius: 99px;
  transform-origin: left center;
  animation: seg-grow 0.7s cubic-bezier(0.4, 0, 0.2, 1) both;
}
@keyframes seg-grow {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}
/* Outcomes legend */
.dash-outcomes-legend { display: flex; flex-direction: column; gap: 9px; }
.dash-outcomes-row {
  display: flex; align-items: center; gap: 8px; font-size: 13px;
}
.dash-outcomes-swatch { width: 10px; height: 10px; border-radius: 3px; flex-shrink: 0; }
.dash-outcomes-label  { color: var(--console-muted); flex: 1; }
.dash-outcomes-val    { font-weight: 700; font-variant-numeric: tabular-nums; }
.dash-outcomes-pct    { font-size: 11px; color: var(--console-muted); min-width: 32px; text-align: right; }

/* ?? Traffic Snapshot Card ?????????????????????????????????????????????? */
.dash-snapshot-rows { display: flex; flex-direction: column; gap: 14px; }
.dash-snapshot-row {
  display: flex; align-items: center; gap: 12px;
  animation: kpi2-enter 0.4s ease-out both;
}
.dash-snapshot-rank {
  width: 20px; height: 20px; border-radius: 6px;
  background: var(--dash-card-border);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 700; color: var(--console-muted);
  flex-shrink: 0;
