.dash-snapshot-mid   { flex: 1; display: flex; flex-direction: column; gap: 5px; }
.dash-snapshot-top   { display: flex; align-items: center; justify-content: space-between; }
.dash-snapshot-label { font-size: 13px; font-weight: 500; color: var(--console-text); }
.dash-snapshot-val   { font-size: 13px; font-weight: 700; font-variant-numeric: tabular-nums; }
.dash-snapshot-track {
  height: 5px; background: var(--dash-card-border);
  border-radius: 99px; overflow: hidden;
}
.dash-snapshot-fill {
  height: 100%; border-radius: 99px;
  transform-origin: left center;
  animation: seg-grow 0.6s cubic-bezier(0.4, 0, 0.2, 1) both;
