.workspace-banners {
  padding: 8px 14px 0;
  display: grid;
  gap: 8px;
}

.console-content {
  flex: 1;
  min-height: 0;
  height: 100%;
  padding: 20px 24px 24px;
  max-width: none;
  margin: 0;
  width: 100%;
  overflow-x: hidden;
  overflow-y: auto;
  background: var(--dash-bg);
}

.console-content:has(> .ch-shell),
.console-content:has(> .vm-shell),
.console-content:has(> .td-page),
.console-content:has(> .billing-ws-shell) {
  height: 100%;
  min-height: 0;
  max-width: none;
  padding: 0;
