}

.page-kicker {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--console-muted);
}

.compact-stack {
  gap: 10px;
}

.panel,
.metric-card,
.state-box,
.settings-nav {
  background: var(--console-panel);
  border-color: var(--console-border);
