}

.metric-card {
  padding: 10px;
}

.metric-label {
  font-size: 11px;
  color: var(--console-muted);
}

.metric-value {
  margin-top: 6px;
  font-size: 18px;
}

.metric-meta {
  font-size: 11px;
  color: var(--console-muted);
}

.btn,
.input,
.select {
  border-radius: 9px;
