}

/* Calls History 2026 */
.calls-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

.calls-toolbar-left,
.calls-toolbar-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.calls-count {
  font-size: 12px;
  color: var(--console-muted);
}

.calls-search {
  width: 260px;
}

.calls-date {
  width: 150px;
}

.calls-page-size {
  min-width: 96px;
}

.calls-history-wrap {
  overflow: auto;
  border: 1px solid var(--console-border);
  border-radius: 10px;
}

.calls-history-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 12px;
}

.calls-history-table thead th {
  text-align: left;
  padding: 10px 9px;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--console-muted);
  border-bottom: 1px solid var(--console-border);
  background: color-mix(in srgb, var(--console-panel-soft) 70%, transparent);
}

.calls-history-table tbody td {
  padding: 10px 9px;
  border-bottom: 1px solid var(--console-border);
}

.calls-history-table tbody tr:nth-child(even) {
  background: color-mix(in srgb, var(--console-panel-soft) 45%, transparent);
}

.calls-history-row {
  cursor: pointer;
  transition: background 0.12s ease;
}

.calls-history-row:hover {
  background: color-mix(in srgb, var(--console-accent) 7%, transparent) !important;
}

.calls-col-icon {
  width: 32px;
}

.calls-dir-icon {
  display: inline-block;
}

.calls-dir-icon.incoming { color: var(--console-success); }
.calls-dir-icon.outgoing { color: var(--console-accent); }
.calls-dir-icon.internal { color: #8f6bff; }

.calls-pagination {
  margin-top: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.audio-row {
  grid-template-columns: minmax(160px, 1fr) auto 170px auto auto auto;
  padding: 8px;
  border-color: var(--console-border);
}

/* ?? Presence Grid animation ??????????????????????????????????????? */
@keyframes presence-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.4; transform: scale(1.35); }
}

/* ?? Floating dialer dialpad key hover ????????????????????????????? */
.dialpad-key:hover {
  background: var(--panel) !important;
}

/* ?? Form label ???????????????????????????????????????????????????? */
.label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-dim);
  margin-bottom: 5px;
  letter-spacing: 0.3px;
}

/* ?? Inline link style ????????????????????????????????????????????? */
.link {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
}

/* ?? Danger ghost button ??????????????????????????????????????????? */
.btn.ghost.danger {
  color: var(--danger);
}
.btn.ghost.danger:hover {
  background: rgba(234,96,104,0.10);
  color: var(--danger);
}

/* ?? Table row base ???????????????????????????????????????????????? */
table tr:hover {
  background: rgba(255,255,255,0.015);
}

/* ?? Stack gap helpers ????????????????????????????????????????????? */
.stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.compact-stack {
  gap: 10px;
}

/* ?? Form layout ??????????????????????????????????????????????????? */
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px 20px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.form-field input[type="password"],
.form-field input[type="number"],
.form-field input[type="email"],
.form-field input[type="time"] {
  font-family: var(--font-mono, monospace);
}

/* ?? Tabs ??????????????????????????????????????????????????????????? */
.tabs {
  display: flex;
  gap: 2px;
  overflow-x: auto;
}

.tab {
  padding: 6px 14px;
  border: none;
  background: transparent;
  color: var(--text-dim);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  white-space: nowrap;
  transition: color 0.15s, border-color 0.15s;
}

.tab:hover {
  color: var(--text);
}

.tab.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-weight: 600;
}

/* ?? Active button state ???????????????????????????????????????????? */
.btn.ghost.active {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

/* Nav backdrop ? hidden on desktop (no overlay needed for push layout) */
.nav-backdrop {
  display: none;
}

@media (max-width: 1080px) {
  /* Mobile: switch to fixed overlay (drawer overlays content below header) */
  .console-body {
    height: calc(100vh - var(--topbar-height));
    overflow: hidden;
  }

  .console-nav {
    position: fixed;
    top: var(--topbar-height);                       /* start below fixed header */
    left: -300px;
    width: 280px;
    height: calc(100vh - var(--topbar-height));
    z-index: 120;
    border-right-width: 1px;
    transition: left 0.22s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .console-nav.open {
    left: 0;
    width: 280px;
    border-right-width: 1px;
    box-shadow: 4px 0 40px rgba(0, 0, 0, 0.4);
  }

  /* Backdrop: only on mobile where drawer is an overlay */
  .nav-backdrop {
    display: block;
    position: fixed;
    top: var(--topbar-height);                       /* start below fixed header */
    left: 0;
    right: 0;
    bottom: 0;
    border: none;
    background: rgba(2, 7, 14, 0.55);
    z-index: 115;
    cursor: pointer;
  }

  .topbar {
    padding: 0 14px;
    gap: 8px;
  }

  .topbar-center {
    min-width: 0;
  }

  .topbar-center .global-search .input {
    width: 100%;
    max-width: none;
  }

  .brand-name {
    display: none;
  }

  .metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dashboard-top-tiles,
  .dashboard-main-grid {
    grid-template-columns: 1fr;
  }
  .dash-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .dash-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .traffic-bar-row {
    grid-template-columns: 86px 1fr 30px;
  }

  .live-traffic-graph {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }

  .chat-layout,
  .settings-layout,
  .grid.two,
  .grid.three {
    grid-template-columns: 1fr;
  }

  .audio-row {
    grid-template-columns: 1fr;
  }
}

