.dash-wide-split {
  display: grid;
  grid-template-columns: 1fr 280px;
  gap: 16px;
  margin-bottom: 20px;
}
.dash-side-stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.dash-three-col {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}
.dash-two-col {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}
.dash-section-hdr {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}
.dash-shell-badge {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: color-mix(in srgb, var(--console-warning) 15%, transparent);
  color: var(--console-warning);
  border: 1px solid color-mix(in srgb, var(--console-warning) 30%, transparent);
  border-radius: 5px;
  padding: 2px 7px;
}

/* -- Call Flow Pipeline -------------------------------------------------------- */
@keyframes flow-step-in {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}
.dash-flow-card {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  box-shadow: var(--dash-shadow);
  padding: 20px 24px;
  margin-bottom: 20px;
  animation: dash-card-in 0.35s ease both;
}
.dash-flow-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.dash-flow-icon { color: var(--console-accent); }
.dash-flow-title {
  font-size: 14px;
  font-weight: 700;
  color: var(--console-text);
}
.dash-flow-sub {
  font-size: 12px;
  color: var(--console-muted);
  margin-left: 4px;
}
.dash-flow-track {
  display: flex;
  align-items: stretch;
  gap: 0;
  overflow-x: auto;
  padding: 4px 0 8px;
}
.dash-flow-step-wrap {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
  animation: flow-step-in 0.4s ease both;
}
.dash-flow-step-wrap:nth-child(1) { animation-delay: 0ms; }
.dash-flow-step-wrap:nth-child(3) { animation-delay: 80ms; }
.dash-flow-step-wrap:nth-child(5) { animation-delay: 160ms; }
.dash-flow-step-wrap:nth-child(7) { animation-delay: 240ms; }
.dash-flow-step-wrap:nth-child(9) { animation-delay: 320ms; }
.dash-flow-step {
  flex: 1;
  border: 1px solid var(--dash-card-border);
  border-radius: 12px;
  padding: 14px 16px;
  background: color-mix(in srgb, var(--flow-color, var(--console-accent)) 6%, var(--dash-card));
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  min-width: 120px;
}
.dash-flow-step:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.2);
}
.dash-flow-step-icon {
  margin-bottom: 8px;
  width: 32px; height: 32px;
  border-radius: 8px;
  background: color-mix(in srgb, currentColor 12%, transparent);
  display: grid; place-items: center;
}
.dash-flow-step-label {
  display: block;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--console-muted);
  margin-bottom: 4px;
}
.dash-flow-step-val {
  display: block;
  font-size: 22px;
  font-weight: 800;
  color: var(--console-text);
  font-variant-numeric: tabular-nums;
}
.dash-flow-step-val--loading { color: var(--console-muted); font-size: 16px; }
.dash-flow-step-val--shell { color: var(--console-muted); font-size: 20px; }
.dash-flow-step-note { display: block; font-size: 10px; color: var(--console-muted); margin-top: 4px; }
.dash-flow-outcome-ok  { color: var(--console-success); font-size: 16px; font-weight: 700; }
.dash-flow-outcome-miss{ color: var(--console-danger);  font-size: 16px; font-weight: 700; }
.dash-flow-arrow {
  font-size: 24px;
  color: var(--console-border);
  padding: 0 6px;
  flex-shrink: 0;
  align-self: center;
  animation: flow-step-in 0.3s ease both;
}

/* -- Activity Heatmap ---------------------------------------------------------- */
.dash-heatmap-card {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  box-shadow: var(--dash-shadow);
  padding: 20px 24px;
  animation: dash-card-in 0.4s ease both;
}
.dash-heatmap-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin: 12px 0;
}
.dash-heatmap-cell {
  flex: 1 0 calc(100% / max(1, var(--cell-count, 24)) - 4px);
  min-width: 14px;
  height: 36px;
  border-radius: 5px;
  cursor: pointer;
  transition: transform 0.1s ease, opacity 0.1s ease;
}
.dash-heatmap-cell:hover { transform: scaleY(1.15); }
.dash-heatmap-cell--skeleton {
  background: var(--console-panel-soft);
  animation: shimmer 1.5s infinite ease;
}
.dash-heatmap-legend {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
}
.dash-heatmap-legend-label { font-size: 11px; color: var(--console-muted); }
.dash-heatmap-legend-bar {
  flex: 1;
  height: 6px;
  border-radius: 3px;
  background: linear-gradient(to right, var(--console-panel-soft), var(--dash-internal), var(--dash-outgoing), var(--dash-incoming));
}
.dash-heatmap-tooltip {
  margin-left: auto;
  font-size: 12px;
  font-weight: 600;
  color: var(--console-text);
  background: var(--console-panel-soft);
  padding: 2px 10px;
  border-radius: 6px;
}

/* -- System Status Card -------------------------------------------------------- */
.dash-status-card {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  box-shadow: var(--dash-shadow);
  padding: 16px 18px;
  animation: dash-card-in 0.4s ease both;
}
.dash-status-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}
.dash-status-orb {
  width: 10px; height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}
.dash-status-orb.ok   { background: var(--console-success); box-shadow: 0 0 0 3px color-mix(in srgb, var(--console-success) 20%, transparent); }
.dash-status-orb.warn { background: var(--console-warning); box-shadow: 0 0 0 3px color-mix(in srgb, var(--console-warning) 20%, transparent); }
.dash-status-title { font-size: 13px; font-weight: 700; color: var(--console-text); }
.dash-status-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 7px;
  margin-bottom: 4px;
  font-size: 12px;
}
.dash-status-row.ok   { background: color-mix(in srgb, var(--console-success) 8%, transparent); }
.dash-status-row.warn { background: color-mix(in srgb, var(--console-warning) 8%, transparent); }
.dash-status-row-icon { width: 18px; display: grid; place-items: center; }
.dash-status-row.ok   .dash-status-row-icon { color: var(--console-success); }
.dash-status-row.warn .dash-status-row-icon { color: var(--console-warning); }
.dash-status-row-label { flex: 1; color: var(--console-text); }
.dash-status-row-pill {
  font-size: 10px; font-weight: 700; letter-spacing: 0.05em;
  text-transform: uppercase; padding: 2px 6px; border-radius: 4px;
}
.dash-status-row-pill.ok   { background: color-mix(in srgb, var(--console-success) 15%, transparent); color: var(--console-success); }
.dash-status-row-pill.warn { background: color-mix(in srgb, var(--console-warning) 15%, transparent); color: var(--console-warning); }

/* -- Time Condition Card ------------------------------------------------------- */
.dash-timecond-card {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  box-shadow: var(--dash-shadow);
  padding: 16px 18px;
  animation: dash-card-in 0.45s ease both;
}
.dash-timecond-status {
  font-size: 28px;
  font-weight: 800;
  letter-spacing: -0.01em;
  margin: 8px 0 4px;
}
.dash-timecond-note { font-size: 11px; color: var(--console-muted); }

/* -- Extension Presence Grid --------------------------------------------------- */
@keyframes presence-in {
  from { opacity: 0; transform: scale(0.95); }
  to   { opacity: 1; transform: scale(1); }
}
.dash-presence-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 12px;
  margin-bottom: 8px;
}
.dash-presence-card {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: 12px;
  padding: 14px 14px 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  transition: box-shadow 0.15s ease, transform 0.15s ease;
  animation: presence-in 0.3s ease both;
}
.dash-presence-card:nth-child(1) { animation-delay: 0ms; }
.dash-presence-card:nth-child(2) { animation-delay: 35ms; }
.dash-presence-card:nth-child(3) { animation-delay: 70ms; }
.dash-presence-card:nth-child(4) { animation-delay: 105ms; }
.dash-presence-card:nth-child(5) { animation-delay: 140ms; }
.dash-presence-card:nth-child(6) { animation-delay: 175ms; }
.dash-presence-card:nth-child(7) { animation-delay: 210ms; }
.dash-presence-card:nth-child(8) { animation-delay: 245ms; }
.dash-presence-card:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.25);
  transform: translateY(-2px);
}
.dash-presence-card--on-call { border-color: color-mix(in srgb, var(--dash-outgoing) 35%, var(--dash-card-border)); }
.dash-presence-card--ringing  { border-color: color-mix(in srgb, var(--console-warning) 40%, var(--dash-card-border)); }
.dash-presence-avatar {
  width: 38px; height: 38px;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--console-accent), #4568f0);
  color: #fff;
  font-size: 12px; font-weight: 700;
  display: grid; place-items: center;
  flex-shrink: 0;
  position: relative;
}
.dash-presence-dot {
  position: absolute;
  bottom: -2px; right: -2px;
  width: 11px; height: 11px;
  border-radius: 50%;
  border: 2px solid var(--dash-card);
}
.dash-presence-info { flex: 1; min-width: 0; }
.dash-presence-name {
  display: block;
  font-size: 12.5px; font-weight: 600;
  color: var(--console-text);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.dash-presence-ext { display: block; font-size: 11px; color: var(--console-muted); }
.dash-presence-status { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; white-space: nowrap; }

/* -- Ops cards shared base ---------------------------------------------------- */
.dash-ops-card {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  box-shadow: var(--dash-shadow);
  padding: 18px 20px;
  animation: dash-card-in 0.4s ease both;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.dash-ops-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}
.dash-ops-icon { color: var(--console-accent); flex-shrink: 0; }
.dash-ops-title { font-size: 14px; font-weight: 700; color: var(--console-text); }
.dash-ops-note  { font-size: 11px; color: var(--console-muted); margin: 4px 0 14px; }

/* Queue metrics grid */
.dash-ops-metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 8px;
}
.dash-ops-metric {
  background: var(--console-panel-soft);
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.dash-ops-metric-val   { font-size: 22px; font-weight: 800; color: var(--console-text); font-variant-numeric: tabular-nums; }
.dash-ops-metric-label { font-size: 11px; font-weight: 600; color: var(--console-text); }
.dash-ops-metric-sub   { font-size: 10px; color: var(--console-muted); }

/* IVR bars */
.dash-ivr-bars { display: flex; flex-direction: column; gap: 8px; margin-top: 8px; }
.dash-ivr-bar-row { display: grid; grid-template-columns: 1fr auto; gap: 6px; align-items: center; }
.dash-ivr-bar-label { font-size: 11px; color: var(--console-text); grid-column: 1 / -1; }
.dash-ivr-bar-track { height: 8px; border-radius: 4px; background: var(--console-panel-soft); overflow: hidden; }
.dash-ivr-bar-fill  { height: 100%; border-radius: 4px; transition: width 0.8s cubic-bezier(0.4, 0, 0.2, 1); }
.dash-ivr-bar-pct   { font-size: 11px; font-weight: 600; color: var(--console-muted); white-space: nowrap; }
.dash-ivr-bar-row { grid-template-columns: 1fr; }

/* Voicemail empty */
.dash-voicemail-empty {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 24px 0; gap: 6px; text-align: center;
}
.dash-voicemail-icon { color: var(--console-muted); opacity: 0.4; }
.dash-voicemail-msg  { font-size: 13px; font-weight: 600; color: var(--console-text); margin: 0; }

/* -- Records card shared base -------------------------------------------------- */
.dash-records-card {
  background: var(--dash-card);
  border: 1px solid var(--dash-card-border);
  border-radius: var(--dash-radius);
  box-shadow: var(--dash-shadow);
  padding: 18px 20px;
  animation: dash-card-in 0.45s ease both;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.dash-records-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 4px;
}
.dash-records-empty {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 28px 0; gap: 6px; text-align: center;
}

/* Billing bars */
.dash-billing-bars { display: flex; flex-direction: column; gap: 12px; margin-top: 12px; }
.dash-billing-row  {}
.dash-billing-row-top {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 5px;
}
.dash-billing-label { font-size: 12px; font-weight: 600; color: var(--console-text); }
.dash-billing-val   { font-size: 11px; color: var(--console-muted); }
.dash-billing-track { height: 7px; border-radius: 4px; background: var(--console-panel-soft); overflow: hidden; }
.dash-billing-fill  { height: 100%; border-radius: 4px; transition: width 0.8s ease; }

/* -- Responsive --------------------------------------------------------------- */
@media (max-width: 1080px) {
  .dash-wide-split  { grid-template-columns: 1fr; }
  .dash-three-col   { grid-template-columns: 1fr; }
  .dash-two-col     { grid-template-columns: 1fr; }
  .dash-flow-track  { flex-wrap: wrap; gap: 10px; }
  .dash-flow-arrow  { display: none; }
}
@media (max-width: 768px) {
  .dash-presence-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ?? Team Directory 2026 ?????????????????????????????????????????????????????? */

@keyframes presence-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.5; transform: scale(1.3); }
}

@keyframes td-toast-in {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes td-panel-in {
  from { transform: translateX(100%); opacity: 0.7; }
  to   { transform: translateX(0);    opacity: 1; }
}

/* Page shell.
   `.console-content:has(> .td-page)` clips this page (overflow: hidden) so the
   hero, toolbar and status bar can stay put — same contract as .ch-shell /
   .vm-shell / .billing-ws-shell. That means the scrolling MUST happen inside,
   on .td-content. With `min-height: 100%` + `overflow: visible` there was no
   scroller anywhere, so any member list taller than the window was simply cut
   off and unreachable — invisible when the window was maximised and the list
   happened to fit, dead the moment the window got shorter. */
.td-page {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  background: var(--bg);
}

/* Presence unavailable banner */
.td-presence-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 16px;
  font-size: 12px;
  font-weight: 500;
  color: var(--warning);
  background: color-mix(in srgb, var(--warning) 8%, var(--panel));
  border-bottom: 1px solid color-mix(in srgb, var(--warning) 22%, var(--border));
  flex-shrink: 0;
}

/* ?? Toolbar ???????????????????????????????????????????????????????????????? */
.td-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--panel);
  flex-shrink: 0;
  flex-wrap: wrap;
}
.td-toolbar-left  { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; flex: 1; min-width: 0; }
.td-toolbar-right { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }

/* Search */
.td-search-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 11px;
  height: 36px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  min-width: 200px;
  max-width: 300px;
  transition: border-color 0.15s ease;
}
.td-search-wrap:focus-within { border-color: var(--accent); }
.td-search-icon { flex-shrink: 0; color: var(--text-dim); }
.td-search {
  flex: 1;
  min-width: 0;
  border: none;
  background: transparent;
  color: var(--text);
  font-size: 13px;
  outline: none;
}
.td-search::placeholder { color: var(--text-dim); }
.td-search-clear {
  border: none;
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  display: flex;
  align-items: center;
  padding: 2px;
  border-radius: 4px;
  transition: color 0.13s;
}
.td-search-clear:hover { color: var(--text); }

/* Filter chips */
.td-filters { display: flex; gap: 4px; align-items: center; flex-wrap: wrap; }
.td-filter-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 20px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-dim);
  font-size: 12px;
  cursor: pointer;
  transition: background 0.13s, color 0.13s, border-color 0.13s;
  white-space: nowrap;
}
.td-filter-chip:hover { border-color: color-mix(in srgb, var(--accent) 40%, var(--border)); color: var(--text); }
.td-filter-chip.active { background: var(--accent); border-color: var(--accent); color: #fff; }
.td-filter-count { font-size: 11px; opacity: 0.72; font-weight: 600; }

/* Sort */
.td-sort-select {
  height: 34px;
  padding: 0 10px;
  border-radius: 9px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  font-size: 12px;
  cursor: pointer;
  outline: none;
}

/* View toggle */
.td-view-toggle {
  display: inline-flex;
  border: 1px solid var(--border);
  border-radius: 9px;
  overflow: hidden;
}
.td-view-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  border: none;
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  transition: background 0.13s, color 0.13s;
}
.td-view-btn:first-child { border-right: 1px solid var(--border); }
.td-view-btn:hover { background: var(--panel-2); color: var(--text); }
.td-view-btn.active { background: var(--accent); color: #fff; }

/* Live badge */
.td-live-badge {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  background: var(--panel-2);
  border: 1px solid var(--border);
}

/* ?? Content area ??????????????????????????????????????????????????????????? */
.td-content {
  flex: 1;
  /* min-height: 0 is what actually lets a flex child shrink below its content
     and become a scroller — without it `flex: 1` still grows to fit every row. */
  min-height: 0;
  overflow-y: auto;
  /* The sideways scroll for a wide list lives here rather than on
     .td-list-wrap, so that .td-content is the ONLY scrollport inside the page.
     A scrollport on .td-list-wrap would capture the list view's sticky
     `.td-thead` — which never scrolls vertically — and the column headers would
     slide out of sight on the way down. */
  overflow-x: auto;
  padding: 16px;
}

/* ?? Card grid ?????????????????????????????????????????????????????????????? */
.td-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(228px, 1fr));
  gap: 14px;
}

/* Member card */
.td-card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  cursor: pointer;
  position: relative;
  outline: none;
  transition: box-shadow 0.2s ease, transform 0.18s ease, border-color 0.18s ease;
}
.td-card:hover {
  box-shadow: 0 6px 24px color-mix(in srgb, #000 18%, transparent);
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--accent) 30%, var(--border));
}
.td-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.td-card-active {
  border-color: color-mix(in srgb, var(--danger) 38%, var(--border));
  background: color-mix(in srgb, var(--danger) 5%, var(--panel));
}
.td-card-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 4px;
}
.td-card-name {
  font-size: 14px;
  font-weight: 650;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.3;
}
.td-card-role { font-size: 12px; color: var(--text-dim); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.td-card-dept { font-size: 11px; color: var(--text-dim); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; opacity: 0.75; }
.td-card-footer { display: flex; align-items: center; gap: 6px; margin-top: 6px; flex-wrap: wrap; }

/* ?? Avatar ????????????????????????????????????????????????????????????????? */
.td-avatar-circle {
  border-radius: 50%;
  background: var(--panel-2);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  color: var(--text-dim);
  letter-spacing: 0.5px;
  flex-shrink: 0;
}

/* ?? Presence dots ?????????????????????????????????????????????????????????? */
.td-presence-dot {
  position: absolute;
  border-radius: 50%;
  border: 2px solid var(--panel);
  flex-shrink: 0;
}
.td-presence-dot-sm {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}
.td-presence-dot-xs {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
  vertical-align: middle;
  margin-right: 3px;
}
.td-presence-dot-pulse { animation: presence-pulse 1.2s ease-in-out infinite; }

/* ?? Status pill & ext badge ???????????????????????????????????????????????? */
.td-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 3px 8px 3px 6px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}
.td-ext-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  background: var(--panel-2);
  border: 1px solid var(--border);
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
}

/* ?? Action menu ???????????????????????????????????????????????????????????? */
.td-action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  transition: background 0.13s, border-color 0.13s, color 0.13s;
}
.td-action-btn:hover { background: var(--panel-2); border-color: var(--border); color: var(--text); }
.td-action-menu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 80;
  min-width: 170px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: 0 12px 36px color-mix(in srgb, #000 22%, transparent);
  padding: 5px;
  animation: td-toast-in 0.14s ease-out;
}
.td-action-item {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 9px 12px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--text);
  font-size: 13px;
  cursor: pointer;
  text-align: left;
  transition: background 0.13s;
}
.td-action-item:hover { background: var(--panel-2); }

/* ?? List / table view ?????????????????????????????????????????????????????? */
/* Deliberately NOT a scrollport — see .td-content. Sideways scrolling for a
   wide table happens on .td-content so `.td-thead`'s sticky header keeps
   working. */
.td-list-wrap { overflow: visible; }
.td-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.td-thead { position: sticky; top: 0; z-index: 10; background: var(--panel); }
.td-th {
  padding: 10px 12px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-dim);
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
  text-align: left;
}
.td-list-row {
  cursor: pointer;
  border-bottom: 1px solid color-mix(in srgb, var(--border) 55%, transparent);
  transition: background 0.13s;
  outline: none;
}
.td-list-row td { padding: 10px 12px; vertical-align: middle; }
.td-list-row:hover { background: color-mix(in srgb, var(--panel-2) 80%, var(--accent) 3%); }
.td-list-row:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.td-list-row-active { background: color-mix(in srgb, var(--danger) 5%, transparent); }
.td-list-row-active:hover { background: color-mix(in srgb, var(--danger) 9%, var(--panel-2)); }

/* Column widths */
.td-col-status  { width: 36px; text-align: center; }
.td-col-name    { min-width: 180px; }
.td-col-ext     { width: 100px; }
.td-col-role    { min-width: 120px; }
.td-col-dept    { min-width: 120px; }
.td-col-state   { width: 150px; }
.td-col-actions { width: 46px; text-align: right; }

.td-list-name-cell { display: flex; align-items: center; gap: 10px; }
.td-list-name { font-weight: 600; color: var(--text); white-space: nowrap; }
.td-list-email { font-size: 11px; color: var(--text-dim); margin-top: 1px; }
.td-muted { color: var(--text-dim); opacity: 0.55; }

/* ?? Detail panel ??????????????????????????????????????????????????????????? */
.td-detail-backdrop {
  position: fixed;
  inset: 0;
  z-index: 90;
  background: rgba(0, 0, 0, 0.32);
}
.td-detail-panel {
  position: fixed;
  top: var(--topbar-height);
  right: 0;
  bottom: 0;
  z-index: 100;
  width: min(380px, 96vw);
  background: var(--panel);
  border-left: 1px solid var(--border);
  box-shadow: -12px 0 40px color-mix(in srgb, #000 20%, transparent);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  padding: 20px;
  gap: 20px;
  animation: td-panel-in 0.22s ease-out;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}
.td-detail-close {
  align-self: flex-end;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text-dim);
  cursor: pointer;
  transition: background 0.13s;
}
.td-detail-close:hover { background: var(--border); color: var(--text); }
.td-detail-profile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border);
}
.td-detail-name { font-size: 18px; font-weight: 700; color: var(--text); margin-top: 4px; }
.td-detail-title { font-size: 13px; color: var(--text-dim); }
.td-detail-dept { font-size: 12px; color: var(--text-dim); opacity: 0.8; }
.td-detail-status-row { display: flex; align-items: center; gap: 6px; margin-top: 4px; }
.td-detail-actions { display: flex; flex-direction: column; gap: 8px; }
.td-detail-cta {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 14px;
  padding: 10px 16px;
  border-radius: 10px;
}
.td-detail-dl {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
}
.td-detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  font-size: 13px;
}
.td-detail-row:last-child { border-bottom: none; }
.td-detail-row dt { color: var(--text-dim); white-space: nowrap; font-weight: 500; }
.td-detail-row dd {
  margin: 0;
  color: var(--text);
  font-weight: 600;
  text-align: right;
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.td-copy-inline {
  border: none;
  background: transparent;
  color: var(--text-dim);
  cursor: pointer;
  padding: 2px 4px;
  border-radius: 5px;
  display: flex;
  align-items: center;
  transition: color 0.13s, background 0.13s;
  flex-shrink: 0;
}
.td-copy-inline:hover { color: var(--text); background: var(--panel-2); }
.td-email-link { color: var(--accent); text-decoration: none; font-size: 12px; overflow: hidden; text-overflow: ellipsis; }
.td-email-link:hover { text-decoration: underline; }

/* ?? Status bar ????????????????????????????????????????????????????????????? */
.td-status-bar {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 16px;
  border-top: 1px solid var(--border);
  background: var(--panel);
  font-size: 12px;
  color: var(--text-dim);
  overflow-x: auto;
}
.td-stat-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}
.td-stat-oncall  { background: color-mix(in srgb, var(--danger)   14%, transparent); color: var(--danger); }
.td-stat-ringing { background: color-mix(in srgb, var(--warning)  14%, transparent); color: var(--warning); }
.td-stat-avail   { background: color-mix(in srgb, var(--success)  14%, transparent); color: var(--success); }
.td-stat-offline { background: color-mix(in srgb, var(--text-dim) 14%, transparent); color: var(--text-dim); }

/* ?? Empty state ???????????????????????????????????????????????????????????? */
.td-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 72px 24px;
  text-align: center;
}
.td-empty-icon-svg { color: color-mix(in srgb, var(--text-dim) 45%, transparent); }
.td-empty-title { font-size: 15px; font-weight: 600; color: var(--text); }
.td-empty-sub { font-size: 13px; color: var(--text-dim); max-width: 320px; line-height: 1.5; }

/* ?? Toast ?????????????????????????????????????????????????????????????????? */
.td-toast {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 200;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--success) 16%, var(--panel));
  border: 1px solid color-mix(in srgb, var(--success) 32%, var(--border));
  color: var(--success);
  font-size: 13px;
  font-weight: 600;
  box-shadow: 0 8px 24px color-mix(in srgb, #000 22%, transparent);
  animation: td-toast-in 0.2s ease-out;
  pointer-events: none;
}

/* ?? Responsive ????????????????????????????????????????????????????????????? */
@media (max-width: 900px) {
  .td-card-grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
  .td-col-role, .td-col-dept { display: none; }
}
@media (max-width: 540px) {
  .td-card-grid { grid-template-columns: 1fr; }
  .td-toolbar { padding: 8px 12px; gap: 8px; }
  .td-search-wrap { min-width: 140px; }
}

/* ?? Live Team Hub redesign ????????????????????????????????????????????????? */
@keyframes td-grid-in {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes td-available-glow {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--success) 24%, transparent); }
  50% { box-shadow: 0 0 0 8px color-mix(in srgb, var(--success) 0%, transparent); }
}
.td-page {
  background: var(--crm-bg, var(--bg));
  color: var(--crm-text, var(--text));
}
.td-hub-hero {
  display: block;
  padding: 20px 20px 0;
}
.td-hub-hero .contacts-header-panel {
  width: 100%;
}
.td-hub-title {
  min-width: 0;
  flex: 1;
  padding: 14px 16px;
  border: 1px solid color-mix(in srgb, var(--border) 72%, transparent);
  border-radius: 18px;
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--panel) 82%, transparent), color-mix(in srgb, var(--panel-2) 72%, transparent));
  box-shadow: 0 18px 50px color-mix(in srgb, #000 18%, transparent);
  backdrop-filter: blur(14px);
}
.td-kicker {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 7px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.td-hub-title h1 {
  font-size: clamp(24px, 3vw, 34px);
  line-height: 0.95;
  letter-spacing: -0.04em;
  margin: 0 0 8px;
}
.td-hub-title p {
  max-width: 720px;
  color: var(--text-dim);
  font-size: 13px;
  line-height: 1.45;
}
.td-hub-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(94px, 1fr));
  gap: 8px;
  min-width: min(360px, 38%);
}
.td-hub-metric {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 88px;
  padding: 12px;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--success) 24%, var(--border));
  background: color-mix(in srgb, var(--success) 9%, var(--panel));
  box-shadow: 0 14px 36px color-mix(in srgb, #000 14%, transparent);
}
.td-hub-metric.danger { border-color: color-mix(in srgb, var(--danger) 28%, var(--border)); background: color-mix(in srgb, var(--danger) 9%, var(--panel)); }
.td-hub-metric.warning { border-color: color-mix(in srgb, var(--warning) 30%, var(--border)); background: color-mix(in srgb, var(--warning) 9%, var(--panel)); }
.td-hub-metric strong {
  font-size: 28px;
  line-height: 1;
  letter-spacing: -0.04em;
}
.td-hub-metric span {
  margin-top: 6px;
  color: var(--text-dim);
  font-size: 12px;
  font-weight: 700;
}
.td-live-strip {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 0 20px 12px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--border) 68%, transparent);
  border-radius: 18px;
  background: color-mix(in srgb, var(--panel) 72%, transparent);
  backdrop-filter: blur(12px);
  overflow: hidden;
}
.td-live-strip-head {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--text);
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
  padding: 0 6px;
}
.td-live-avatars {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  scrollbar-width: none;
}
.td-live-avatars::-webkit-scrollbar { display: none; }
.td-live-avatar {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: max-content;
  padding: 5px 10px 5px 5px;
  border: 1px solid color-mix(in srgb, var(--border) 62%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--panel-2) 72%, transparent);
  color: var(--text);
  cursor: pointer;
  transition: transform 0.18s ease, background 0.18s ease;
}
.td-live-avatar:hover { transform: translateY(-1px); background: color-mix(in srgb, var(--accent) 10%, var(--panel-2)); }
.td-live-avatar > span { max-width: 140px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; font-weight: 700; }
.td-live-empty { color: var(--text-dim); font-size: 13px; }
.td-toolbar {
  align-items: stretch;
  flex-direction: column;
  gap: 12px;
  flex-wrap: nowrap;
  margin: 0 20px 12px;
  padding: 12px 0 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
}
.td-toolbar-filter-card {
  width: 100%;
  justify-content: space-between;
  border-color: var(--crm-border);
  background: color-mix(in srgb, var(--crm-surface) 96%, var(--crm-bg));
}
.td-search-wrap,
.td-sort-select,
.td-view-toggle {
  border-color: color-mix(in srgb, var(--crm-border) 80%, transparent);
  background: color-mix(in srgb, var(--crm-surface-2) 92%, transparent);
}
.td-search {
  border: 0 !important;
  background: transparent !important;
  color: var(--crm-text) !important;
  box-shadow: none !important;
}
.td-search::placeholder {
  color: color-mix(in srgb, var(--crm-text-muted) 78%, transparent) !important;
}
.td-filter-chip {
  padding: 6px 11px;
  border: 1px solid color-mix(in srgb, var(--crm-border) 80%, transparent);
  background: color-mix(in srgb, var(--crm-surface-2) 90%, transparent);
  color: var(--crm-text-muted);
  transition: transform 0.18s ease, background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
}
.td-filter-chip:hover { transform: translateY(-1px); }
.td-filter-chip.active {
  background: var(--crm-accent);
  border-color: color-mix(in srgb, var(--crm-accent) 55%, transparent);
  color: #fff;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12);
}
.td-view-toggle { border-radius: 999px; padding: 3px; gap: 3px; }
.td-view-btn {
  width: auto;
  min-width: 72px;
  gap: 6px;
  border-radius: 999px;
  padding: 0 11px;
  font-size: 12px;
  font-weight: 800;
}
.td-view-btn:first-child { border-right: none; }
.td-view-btn.active {
  background: color-mix(in srgb, var(--crm-accent) 14%, var(--crm-surface-2));
  color: var(--crm-accent);
}
.td-content { padding: 0 20px 18px; }
.td-card-grid {
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 10px;
}
.td-smart-card {
  min-height: 132px;
  padding: 12px;
  border-radius: 16px;
  border: 1px solid color-mix(in srgb, var(--border) 62%, transparent);
  background:
    radial-gradient(circle at 80% 0%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 44%),
    color-mix(in srgb, var(--panel) 82%, transparent);
  box-shadow: 0 10px 24px color-mix(in srgb, #000 11%, transparent);
  backdrop-filter: blur(10px);
  animation: td-grid-in 0.36s ease both;
  transform-origin: center;
}
.td-smart-card:hover {
  transform: translateY(-2px) scale(1.01);
  box-shadow: 0 18px 42px color-mix(in srgb, #000 18%, transparent);
  border-color: color-mix(in srgb, var(--accent) 36%, var(--border));
}
.td-smart-card.td-presence-available {
  background:
    radial-gradient(circle at 82% 0%, color-mix(in srgb, var(--success) 12%, transparent), transparent 42%),
    color-mix(in srgb, var(--panel) 82%, transparent);
}
.td-card-active {
  background:
    radial-gradient(circle at 82% 0%, color-mix(in srgb, var(--danger) 13%, transparent), transparent 42%),
    color-mix(in srgb, var(--panel) 84%, transparent);
}
.td-card-top { align-items: flex-start; }
.td-status-pill-float { margin-left: auto; }
.td-card-name {
  margin-top: 6px;
  font-size: 15px;
  font-weight: 780;
  letter-spacing: -0.02em;
}
.td-card-ext {
  color: var(--text-dim);
  font-size: 12px;
  font-weight: 700;
}
.td-card-role,
.td-card-dept { display: none; }
.td-card-footer {
  margin-top: auto;
  padding-top: 8px;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 0.18s ease, transform 0.18s ease;
}
.td-smart-card:hover .td-card-footer,
.td-smart-card:focus-within .td-card-footer {
  opacity: 1;
  transform: translateY(0);
}
.td-hover-action {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 28px;
  padding: 0 9px;
  border: 1px solid color-mix(in srgb, var(--border) 62%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--panel-2) 72%, transparent);
  color: var(--text);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}
.td-hover-action:hover { background: color-mix(in srgb, var(--accent) 13%, var(--panel-2)); }
.td-qr-pill {
  width: 28px;
  min-width: 28px;
  padding: 0;
  justify-content: center;
  gap: 0;
}
.td-avatar-wrap {
  position: relative;
  flex-shrink: 0;
}
.td-avatar-circle {
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 70%, var(--panel-2)), var(--panel-2));
  color: var(--text);
  border: 1px solid color-mix(in srgb, #fff 10%, var(--border));
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 16%, transparent);
}
.td-avatar-wrap.td-presence-available .td-avatar-circle { animation: td-available-glow 2.2s ease-in-out infinite; }
.td-presence-dot {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--panel) 90%, transparent), 0 0 18px currentColor;
}
.td-clean-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: visible;
}
.td-clean-row {
  display: grid;
  grid-template-columns: minmax(220px, 1.4fr) minmax(120px, 0.8fr) auto auto;
  align-items: center;
  gap: 16px;
  padding: 9px 12px;
  border: 1px solid color-mix(in srgb, var(--border) 54%, transparent);
  border-radius: 14px;
  background: color-mix(in srgb, var(--panel) 74%, transparent);
  backdrop-filter: blur(10px);
  animation: td-grid-in 0.24s ease both;
}
.td-clean-row:hover {
  background: color-mix(in srgb, var(--accent) 7%, var(--panel));
  transform: translateY(-1px);
  box-shadow: 0 14px 34px color-mix(in srgb, #000 14%, transparent);
}
.td-list-row { border-bottom: none; }
.td-list-row td { padding: 0; }
.td-list-name-cell { gap: 12px; }
.td-list-name { font-size: 13px; font-weight: 760; }
.td-list-email { margin-top: 3px; }
.td-list-meta {
  display: flex;
  flex-direction: column;
  min-width: 0;
  color: var(--text);
  font-size: 13px;
  font-weight: 700;
}
.td-list-meta small {
  margin-top: 3px;
  color: var(--text-dim);
  font-weight: 600;
}
.td-row-actions {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
  opacity: 0;
  transform: translateX(6px);
  transition: opacity 0.18s ease, transform 0.18s ease;
}
