  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 14px 18px 0;
}
.cc-new-options button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 38px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--panel-2);
  color: var(--text-dim);
  cursor: pointer;
}
.cc-new-options button.active { border-color: var(--accent); color: var(--text); background: color-mix(in srgb, var(--accent) 12%, var(--panel-2)); }
.cc-form-stack {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 18px;
  overflow: auto;
}
.cc-form-stack label:not(.cc-people-search) {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;
  color: var(--text-dim);
}
.cc-form-stack input {
  min-height: 40px;
  border-radius: 12px;
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  padding: 0 12px;
  outline: none;
}
.cc-form-error { color: var(--danger); font-size: 12px; }
.cc-form-hint { color: var(--text-dim); font-size: 12px; }
.cc-people-search { margin: 0; }
.cc-people-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-height: 280px;
  overflow: auto;
}
.cc-people-list button {
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 10px 12px;
  background: var(--panel-2);
  color: var(--text);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  cursor: pointer;
}
.cc-people-list button.active { border-color: var(--accent); background: color-mix(in srgb, var(--accent) 12%, var(--panel-2)); }
.cc-people-list span { color: var(--text-dim); font-size: 12px; margin-top: 2px; }
.cc-toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 260;
  padding: 10px 14px;
  border-radius: 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--border));
  background: var(--panel);
  color: var(--text);
  box-shadow: var(--shadow);
}

/* Light mode polish ? scoped to light theme only. Dark selectors/tokens stay untouched. */
:root[data-theme="light"] {
  color-scheme: light;
