.uau-initials {
  font-size: inherit;
  line-height: 1;
}
.uau-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}
.uau-loading {
  background: rgba(0, 0, 0, 0.45);
  pointer-events: all;
}
.uau-hover-overlay {
  background: rgba(0, 0, 0, 0.45);
  opacity: 0;
  transition: opacity 0.15s;
}
.uau-editable:hover .uau-hover-overlay {
  opacity: 1;
}
.uau-spin {
  animation: uau-spin 0.8s linear infinite;
}
@keyframes uau-spin {
  to { transform: rotate(360deg); }
}
.uau-remove {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 16px;
  height: 16px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.65);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s;
  z-index: 2;
}
.uau-editable:hover .uau-remove {
  opacity: 1;
}
.uau-error {
  position: absolute;
  bottom: calc(100% + 5px);
  left: 50%;
  transform: translateX(-50%);
  background: #c0392b;
  color: #fff;
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 4px;
  white-space: nowrap;
  z-index: 20;
  pointer-events: none;
}

/* Ensure profile-trigger-avatar keeps its rounded shape when showing photo */
.profile-trigger-avatar.uau-wrap {
  border-radius: 50%;
}

/* Light-theme overrides for uau-wrap initials background */
:root[data-theme="light"] .uau-wrap {
  background: linear-gradient(145deg, #4e6ef7, #2d52e0);
}

/* ?? Dashboard v2 (2026 redesign) ???????????????????????????????????????????? */
.dash-v2-shell {
  display: flex;
  flex-direction: column;
  gap: 22px;
  padding: 22px 24px 36px;
  max-width: 1440px;
  margin: 0 auto;
  width: 100%;
}

/* Page-load stagger: each top-level section fades up with a gentle delay. */
@keyframes dashV2FadeUp {
  from { opacity: 0; transform: translate3d(0, 10px, 0); }
  to   { opacity: 1; transform: translate3d(0, 0, 0); }
}
@keyframes dashV2GraphReveal {
  from { opacity: 0; transform: scale(0.98); }
  to   { opacity: 1; transform: scale(1); }
}
@keyframes dashV2KpiPop {
  0%   { opacity: 0; transform: translate3d(0, 8px, 0) scale(0.985); }
  60%  { opacity: 1; }
  100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
}

.dash-v2-shell > * {
  animation: dashV2FadeUp 0.5s cubic-bezier(0.22, 0.7, 0.25, 1) both;
  will-change: transform, opacity;
}
.dash-v2-shell > *:nth-child(1) { animation-delay: 0ms; }
.dash-v2-shell > *:nth-child(2) { animation-delay: 70ms; }
.dash-v2-shell > *:nth-child(3) { animation-delay: 140ms; }
.dash-v2-shell > *:nth-child(4) { animation-delay: 210ms; }
.dash-v2-shell > *:nth-child(5) { animation-delay: 280ms; }
.dash-v2-shell > *:nth-child(6) { animation-delay: 350ms; }

/* Inner-stagger for the 5 KPI cards so the row feels alive. */
.workspace-overview .crm-queue-kpi-strip .crm-queue-kpi-card {
  animation: dashV2FadeUp 0.48s cubic-bezier(0.22, 0.7, 0.25, 1) both;
}
.workspace-overview .crm-queue-kpi-strip .crm-queue-kpi-card:nth-child(1) { animation-delay: 200ms; }
.workspace-overview .crm-queue-kpi-strip .crm-queue-kpi-card:nth-child(2) { animation-delay: 240ms; }
.workspace-overview .crm-queue-kpi-strip .crm-queue-kpi-card:nth-child(3) { animation-delay: 280ms; }
.workspace-overview .crm-queue-kpi-strip .crm-queue-kpi-card:nth-child(4) { animation-delay: 320ms; }
.workspace-overview .crm-queue-kpi-strip .crm-queue-kpi-card:nth-child(5) { animation-delay: 360ms; }

/* Soft scale-in on the call-volume chart card. */
.dash-v2-graph .dash-v2-graph-card {
  animation: dashV2GraphReveal 0.6s cubic-bezier(0.22, 0.7, 0.25, 1) both;
  animation-delay: 100ms;
  transform-origin: center top;
}

/* Stagger active-call rows so newly fetched calls cascade in. */
.dash-v2-active-list .dash-v2-active-row {
  animation: dashV2FadeUp 0.4s cubic-bezier(0.22, 0.7, 0.25, 1) both;
}
.dash-v2-active-list .dash-v2-active-row:nth-child(1) { animation-delay: 280ms; }
.dash-v2-active-list .dash-v2-active-row:nth-child(2) { animation-delay: 320ms; }
.dash-v2-active-list .dash-v2-active-row:nth-child(3) { animation-delay: 360ms; }
.dash-v2-active-list .dash-v2-active-row:nth-child(4) { animation-delay: 400ms; }
.dash-v2-active-list .dash-v2-active-row:nth-child(n + 5) { animation-delay: 440ms; }

/* Honour user motion preferences. */
@media (prefers-reduced-motion: reduce) {
  .dash-v2-shell > *,
  .workspace-overview .crm-queue-kpi-strip .crm-queue-kpi-card,
  .dash-v2-graph .dash-v2-graph-card,
  .dash-v2-active-list .dash-v2-active-row {
    animation: none !important;
  }
}

