}
.dash-v2-graph-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 4px;
}
.dash-v2-graph-head-title {
  display: flex;
  align-items: center;
  gap: 10px;
}
.dash-v2-graph-head-title h2 {
  font-size: 15px;
  font-weight: 600;
  color: var(--console-text);
  margin: 0;
}
.dash-v2-graph-icon {
  width: 28px; height: 28px;
