:root[data-theme="light"] .dash-v2-kpi-card.dash-v2-card {
  background: linear-gradient(180deg, #ffffff, #f7f9fc);
  border: 1px solid #cbd5e1;
  box-shadow: 0 6px 18px rgba(15, 23, 42, 0.06);
}
:root[data-theme="light"] .dash-v2-kpi-card.dash-v2-card:hover,
:root[data-theme="light"] .dash-v2-card:hover {
  border-color: #94a3b8;
}
:root[data-theme="light"] .dash-filter-pills,
:root[data-theme="light"] .dash-filter-custom {
  background: #ffffff;
  border-color: #e2e8f0;
}
:root[data-theme="light"] .dash-v2-active-row {
  background: #ffffff;
  border-color: #e2e8f0;
}

/* Workspace Overview: light, professional elevated cards. */
:root[data-theme="light"] .workspace-overview {
  --workspace-card-border: rgba(148, 163, 184, 0.54);
  --workspace-card-border-hover: rgba(100, 116, 139, 0.62);
  --workspace-card-shadow:
    0 1px 1px rgba(15, 23, 42, 0.035),
    0 14px 30px -20px rgba(30, 41, 59, 0.34),
    0 28px 58px -38px rgba(37, 99, 235, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);
  --workspace-card-shadow-hover:
    0 1px 1px rgba(15, 23, 42, 0.045),
    0 18px 38px -22px rgba(30, 41, 59, 0.4),
    0 36px 72px -42px rgba(37, 99, 235, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.96);
}

:root[data-theme="light"] .workspace-overview .dash-v2-card {
