}

:root[data-theme="light"] .workspace-overview .dash-v2-card > * {
  position: relative;
  z-index: 1;
}

:root[data-theme="light"] .workspace-overview .dash-v2-card:hover {
  border-color: var(--workspace-card-border-hover);
  box-shadow: var(--workspace-card-shadow-hover);
}

:root[data-theme="light"] .workspace-overview .dash-v2-graph-card {
  overflow: visible;
  box-shadow:
    0 1px 1px rgba(15, 23, 42, 0.035),
    0 18px 38px -24px rgba(30, 41, 59, 0.38),
    0 36px 76px -44px rgba(37, 99, 235, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
}

:root[data-theme="light"] .workspace-overview .dash-v2-comm-card:nth-child(1) {
  background:
    radial-gradient(circle at 92% 0%, rgba(16, 185, 129, 0.12), transparent 30%),
    linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
}

:root[data-theme="light"] .workspace-overview .dash-v2-comm-card:nth-child(2) {
  background:
    radial-gradient(circle at 92% 0%, rgba(59, 130, 246, 0.13), transparent 30%),
    linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
}

:root[data-theme="light"] .workspace-overview .dash-v2-active-row,
:root[data-theme="light"] .workspace-overview .dash-v2-ivr-stat,
:root[data-theme="light"] .workspace-overview .dash-v2-comm-item .dash-v2-comm-item-link {
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.88) inset,
    0 10px 22px -20px rgba(15, 23, 42, 0.32);
}

:root[data-theme="light"] .workspace-overview .dash-v2-active-row,
:root[data-theme="light"] .workspace-overview .dash-v2-comm-item .dash-v2-comm-item-link,
:root[data-theme="light"] .workspace-overview .dash-v2-comm-cta {
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.18s ease, transform 0.18s ease, gap 0.15s ease;
}

:root[data-theme="light"] .workspace-overview .dash-v2-active-row:hover,
:root[data-theme="light"] .workspace-overview .dash-v2-comm-item .dash-v2-comm-item-link:hover {
