  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.94) inset,
    0 14px 28px -22px rgba(15, 23, 42, 0.38);
}

/* CRM dashboard light mode ? scoped warm SaaS workspace. Dark mode keeps the existing CRM system. */
:root[data-theme="light"] .crm-dashboard-shell {
  --crm-light-page: #f8f2e9;
  --crm-light-page-2: #eef5ff;
  --crm-light-panel: rgba(255, 255, 255, 0.92);
  --crm-light-panel-strong: #ffffff;
  --crm-light-panel-soft: rgba(255, 250, 243, 0.82);
  --crm-light-border: rgba(201, 187, 171, 0.54);
  --crm-light-border-strong: rgba(119, 139, 171, 0.24);
  --crm-light-text: #213047;
  --crm-light-muted: #718096;
  --crm-light-accent: #377dff;
  --crm-light-purple: #8b5cf6;
  --crm-light-success: #15a46c;
  --crm-light-warning: #d97706;
  --crm-light-danger: #e14d5a;
  --crm-light-shadow: 0 22px 55px rgba(74, 63, 53, 0.12);
  --crm-light-shadow-soft: 0 12px 32px rgba(74, 63, 53, 0.08);
  --crm-light-radius: 26px;
  background:
    radial-gradient(circle at 14% -10%, rgba(255, 181, 91, 0.24), transparent 31%),
