}

:root[data-theme="dark"] .crm-dashboard-ops-panel,
:root[data-theme="dark"] .crm-dashboard-main-stack > .grid {
  grid-column: 1 / span 8;
}

:root[data-theme="dark"] .crm-dashboard-right-rail {
  grid-column: 9 / -1;
  grid-row: 2 / span 2;
}

:root[data-theme="light"] .crm-dashboard-shell .console-content {
