:root[data-theme="light"] .crm-dashboard-shell .console-nav {
  /* inherits standard console-nav background */
}

:root[data-theme="light"] .crm-dashboard-shell .drawer-nav-link {
  border-radius: 16px;
  color: #62708a;
  font-weight: 650;
  letter-spacing: -0.01em;
}

:root[data-theme="light"] .crm-dashboard-shell .drawer-nav-link:hover {
