  border-color: rgba(91, 141, 255, 0.22);
  box-shadow: 0 16px 30px rgba(55, 125, 255, 0.13), inset 0 1px 0 rgba(255, 255, 255, 0.88);
}

:root[data-theme="light"] .crm-dashboard-shell .drawer-nav-link.active .drawer-nav-icon,
:root[data-theme="light"] .crm-dashboard-shell .drawer-nav-link:hover .drawer-nav-icon {
