  border-color: rgba(197, 181, 160, 0.56);
  box-shadow: 0 10px 22px rgba(70, 59, 44, 0.07);
}

:root[data-theme="light"] .crm-dashboard-workspace {
  --crm-bg: transparent;
  --crm-surface: var(--crm-light-panel);
  --crm-surface-2: rgba(251, 246, 239, 0.86);
  --crm-text: var(--crm-light-text);
