  --crm-border: var(--crm-light-border);
  --crm-accent: var(--crm-light-accent);
  --crm-success: var(--crm-light-success);
  --crm-warning: var(--crm-light-warning);
  --crm-danger: var(--crm-light-danger);
  color: var(--crm-light-text);
  background: transparent;
  transition: background 180ms ease, color 180ms ease;
}

:root[data-theme="light"] .crm-dashboard-inner {
  gap: 18px;
  padding-top: 28px;
  padding-bottom: 42px;
}

:root[data-theme="light"] .crm-dashboard-hero {
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 132px;
  padding: 14px 2px 8px !important;
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
}

:root[data-theme="light"] .crm-dashboard-hero > * {
  position: relative;
  z-index: 2;
}

:root[data-theme="light"] .crm-dashboard-hero-scene {
  position: absolute;
  right: 0;
  bottom: -14px;
  height: 138%;
  width: min(760px, 74%);
  opacity: 1;
  transform-origin: bottom right;
  animation: crm-hero-scene-in 900ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes crm-hero-scene-in {
  0% {
    opacity: 0;
    transform: translateY(14px) scale(1.02);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

/* Gentle drifting glow behind the sun once the scene has loaded. */
:root[data-theme="light"] .crm-dashboard-hero-scene .crm-hero-sun-glow {
  transform-box: fill-box;
  transform-origin: center;
  animation: crm-hero-sun-pulse 6s ease-in-out 900ms infinite;
}

@keyframes crm-hero-sun-pulse {
  0%, 100% { opacity: 0.85; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.06); }
}

@media (prefers-reduced-motion: reduce) {
  :root[data-theme="light"] .crm-dashboard-hero-scene,
  :root[data-theme="light"] .crm-dashboard-hero-scene .crm-hero-sun-glow {
    animation: none;
  }
}

:root[data-theme="light"] .crm-dashboard-hero h1 {
  font-size: clamp(2.05rem, 3vw, 3.15rem);
  line-height: 0.98;
  letter-spacing: -0.055em;
  color: #18263c;
}

:root[data-theme="light"] .crm-dashboard-hero p {
  margin-top: 10px;
  max-width: 720px;
  font-size: 1rem;
  line-height: 1.55;
  color: #6f7989;
}

:root[data-theme="light"] .crm-dashboard-hero .crm-dashboard-header-action,
:root[data-theme="light"] .crm-dashboard-workspace a.crm-dashboard-header-action {
  min-height: 38px;
  border-radius: 999px;
