/* CRM queue premium light workspace. Dark mode keeps the existing CRM token surfaces. */
.crm-queue-priority-section {
  min-width: 0;
}

.crm-queue-main-workspace,
.crm-queue-center-workspace {
  min-width: 0;
  min-height: 0;
  flex: 1;
  height: 100%;
}

.crm-queue-priority-icon,
.crm-queue-rail-icon,
.crm-queue-quick-action-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.crm-queue-mini-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--crm-border);
  border-radius: 12px;
  background: var(--crm-surface-2);
  color: var(--crm-text);
  font-size: 12px;
  font-weight: 700;
  text-decoration: none;
  transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
}

.crm-queue-mini-link {
  min-width: 0;
  padding: 8px 9px;
}

.crm-queue-mini-link:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--crm-accent) 38%, var(--crm-border));
  background: color-mix(in srgb, var(--crm-accent) 8%, var(--crm-surface-2));
}

.crm-queue-empty-workspace {
  position: relative;
  overflow: hidden;
}

.crm-queue-empty-glow {
  pointer-events: none;
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 18% 18%, color-mix(in srgb, var(--crm-accent) 14%, transparent), transparent 32%),
    radial-gradient(circle at 88% 5%, color-mix(in srgb, var(--crm-success) 10%, transparent), transparent 30%);
}

.crm-queue-illustration {
  border-radius: 999px;
  background:
    radial-gradient(circle, color-mix(in srgb, var(--crm-accent) 12%, transparent), transparent 58%),
    color-mix(in srgb, var(--crm-surface-2) 68%, transparent);
}

.crm-queue-clipboard {
  position: relative;
  display: flex;
  width: 124px;
  height: 150px;
  align-items: center;
  justify-content: center;
  border: 8px solid color-mix(in srgb, var(--crm-accent) 34%, transparent);
  border-radius: 28px;
  color: var(--crm-accent);
  background: var(--crm-surface);
  box-shadow: 0 18px 45px -20px color-mix(in srgb, var(--crm-accent) 48%, transparent);
}

.crm-queue-clipboard::before {
  content: "";
  position: absolute;
  top: -24px;
  width: 54px;
  height: 30px;
  border-radius: 16px 16px 8px 8px;
  background: color-mix(in srgb, var(--crm-accent) 62%, white);
}

.crm-queue-check {
  position: absolute;
  left: 28px;
  width: 12px;
  height: 7px;
  border-bottom: 2px solid var(--crm-success);
  border-left: 2px solid var(--crm-success);
  transform: rotate(-45deg);
}

.crm-queue-check-1 { top: 54px; }
.crm-queue-check-2 { top: 78px; }
.crm-queue-check-3 { top: 102px; }

.crm-queue-success-pill {
  border-color: color-mix(in srgb, var(--crm-success) 34%, var(--crm-border));
  background: color-mix(in srgb, var(--crm-success) 10%, var(--crm-surface));
  color: var(--crm-success);
}

.crm-queue-quick-action,
.crm-queue-priority-card {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--crm-border);
  border-radius: 14px;
  background: var(--crm-surface-2);
  color: var(--crm-text);
  text-decoration: none;
  transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.crm-queue-quick-action {
  padding: 12px;
}

.crm-queue-quick-action-icon,
.crm-queue-priority-icon {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  color: var(--crm-accent);
  background: color-mix(in srgb, var(--crm-accent) 12%, var(--crm-surface));
}

.crm-queue-quick-action:hover,
.crm-queue-priority-card:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--crm-accent) 36%, var(--crm-border));
  box-shadow: 0 18px 38px -26px rgba(0, 0, 0, 0.55);
}

.crm-queue-priority-card {
  padding: 14px;
}

.crm-queue-detail-rail .crm-workspace-right-rail-scroll {
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: 100%;
