/* CRM Live Call Workspace light-mode cockpit. */
.crm-live-workspace {
  width: 100%;
  min-width: 0;
}

.crm-live-hero,
.crm-live-card,
.crm-live-kpi-card,
.crm-live-performance-bar {
  border: 1px solid var(--crm-border);
  background: var(--crm-surface);
  color: var(--crm-text);
  box-shadow: var(--crm-shadow, 0 18px 48px -28px rgba(0, 0, 0, 0.42));
  transition:
    background 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.crm-live-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  overflow: hidden;
  border-radius: 28px;
  padding: 1.1rem 1.25rem;
}

.crm-live-hero-icon,
.crm-live-kpi-icon,
.crm-live-feed-icon {
  display: flex;
  align-items: center;
  justify-content: center;
}

.crm-live-hero-icon {
  height: 3.25rem;
  width: 3.25rem;
  flex-shrink: 0;
  border-radius: 1.15rem;
  background: color-mix(in srgb, var(--crm-accent) 16%, var(--crm-surface-2));
  color: var(--crm-accent);
}

.crm-live-title {
  font-size: clamp(1.55rem, 2vw, 2.15rem);
  font-weight: 800;
  letter-spacing: -0.045em;
  line-height: 1;
  color: var(--crm-text);
}

.crm-live-subtitle {
  margin-top: 0.35rem;
  max-width: 42rem;
  color: var(--crm-text-muted);
  font-size: 0.92rem;
  line-height: 1.45;
}

.crm-live-hero-actions,
.crm-live-chip-row,
.crm-live-controls,
.crm-live-quick-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
}

.crm-live-status-pill,
.crm-live-stage-pill,
.crm-live-soft-chip,
.crm-live-mini-chip,
.crm-live-queue-status {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border-radius: 999px;
  white-space: nowrap;
}

.crm-live-status-pill {
  min-height: 2.35rem;
  border: 1px solid var(--crm-border);
  background: var(--crm-surface-2);
  padding: 0 0.8rem;
  color: var(--crm-text-muted);
  font-size: 0.78rem;
  font-weight: 750;
}

.crm-live-status-pill.is-online {
  border-color: color-mix(in srgb, var(--crm-success) 28%, var(--crm-border));
  background: color-mix(in srgb, var(--crm-success) 12%, var(--crm-surface));
  color: var(--crm-success);
}

.crm-live-primary-action,
.crm-live-secondary-action,
.crm-live-icon-action,
.crm-live-card-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.95rem;
  font-size: 0.82rem;
  font-weight: 750;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    color 160ms ease,
    transform 160ms ease;
}

.crm-live-primary-action,
.crm-live-workspace .tasks-primary-action,
.crm-live-workspace a.tasks-primary-action {
  min-height: 2.35rem;
  border: 1px solid transparent;
  background: var(--crm-accent);
  padding: 0 0.95rem;
  color: #fff;
  box-shadow: 0 14px 24px -18px color-mix(in srgb, var(--crm-accent) 70%, #000);
}

.crm-live-workspace .tasks-primary-action,
.crm-live-workspace a.tasks-primary-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border-radius: 0.85rem;
  font-size: 0.875rem;
  font-weight: 700;
  text-decoration: none;
}

.crm-live-secondary-action,
.crm-live-icon-action,
.crm-live-card-link {
  border: 1px solid var(--crm-border);
  background: var(--crm-surface-2);
  color: var(--crm-text);
}

.crm-live-secondary-action {
  min-height: 2.25rem;
  padding: 0 0.9rem;
}

.crm-live-icon-action {
  height: 2.35rem;
  width: 2.35rem;
  padding: 0;
}

.crm-live-card-link {
  margin-top: 0.75rem;
  min-height: 2.2rem;
  width: 100%;
  padding: 0 0.8rem;
}

.crm-live-primary-action:not(:disabled):hover,
.crm-live-workspace .tasks-primary-action:hover,
.crm-live-workspace a.tasks-primary-action:hover,
.crm-live-secondary-action:not(:disabled):hover,
.crm-live-icon-action:not(:disabled):hover,
.crm-live-card-link:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 30px -24px rgba(20, 31, 48, 0.55);
}

.crm-live-primary-action:disabled,
.crm-live-secondary-action:disabled,
.crm-live-icon-action:disabled,
.crm-live-control:disabled,
.crm-live-tab:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.crm-live-kpi-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.8rem;
}

.crm-live-kpi-card {
  min-height: 6rem;
  border-radius: 22px;
  padding: 0.78rem;
}

.crm-live-kpi-card:hover,
.crm-live-card:hover {
  transform: translateY(-1px);
}

.crm-live-kpi-icon {
  height: 2.35rem;
  width: 2.35rem;
  border-radius: 0.9rem;
  background: color-mix(in srgb, var(--crm-accent) 13%, var(--crm-surface-2));
  color: var(--crm-accent);
}

.crm-live-kpi-card.tone-green .crm-live-kpi-icon,
.crm-live-kpi-card.tone-emerald .crm-live-kpi-icon {
  background: color-mix(in srgb, var(--crm-success) 14%, var(--crm-surface-2));
  color: var(--crm-success);
}

.crm-live-kpi-card.tone-violet .crm-live-kpi-icon {
  background: color-mix(in srgb, #7c3aed 15%, var(--crm-surface-2));
  color: #7c3aed;
}

.crm-live-kpi-card.tone-amber .crm-live-kpi-icon {
  background: color-mix(in srgb, var(--crm-warning) 15%, var(--crm-surface-2));
  color: var(--crm-warning);
}

.crm-live-kpi-card.tone-cyan .crm-live-kpi-icon {
  background: color-mix(in srgb, #0891b2 14%, var(--crm-surface-2));
  color: #0891b2;
}

.crm-live-kpi-label,
.crm-live-section-label {
  color: var(--crm-text-muted);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.075em;
  text-transform: uppercase;
}

.crm-live-kpi-value {
  margin-top: 0.25rem;
  color: var(--crm-text);
  font-size: clamp(1.6rem, 2vw, 2rem);
  font-weight: 850;
  letter-spacing: -0.055em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.crm-live-kpi-trend {
  color: var(--crm-success);
  font-size: 0.7rem;
  font-weight: 750;
}

.crm-live-cockpit-grid {
  display: grid;
  grid-template-columns: minmax(17rem, 1.05fr) minmax(22rem, 1.2fr) minmax(17rem, 1fr);
  align-items: start;
  gap: 0.9rem;
}

.crm-live-main-stack,
.crm-live-center-stack,
.crm-live-side-stack {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 0.9rem;
}

.crm-live-card {
  min-width: 0;
  overflow: hidden;
  border-radius: 24px;
  padding: 0.85rem;
}

.crm-live-active-card {
  padding: 0.9rem;
}

.crm-live-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.65rem;
}

.crm-live-section-title {
  color: var(--crm-text);
  font-size: 0.96rem;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.crm-live-timer {
  color: var(--crm-text);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.8rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.crm-live-dot {
  height: 0.45rem;
  width: 0.45rem;
  border-radius: 999px;
  background: var(--crm-text-muted);
}

.crm-live-dot.is-live {
  animation: pulse 1.5s infinite;
  background: var(--crm-success);
  box-shadow: 0 0 0 5px color-mix(in srgb, var(--crm-success) 14%, transparent);
}

.crm-live-contact-hero {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.9rem;
  padding: 0.2rem 0 0.65rem;
}

.crm-live-avatar {
  display: flex;
  height: 3.85rem;
  width: 3.85rem;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 1.35rem;
  color: #fff;
  font-size: 1.25rem;
  font-weight: 850;
  box-shadow: 0 18px 30px -24px rgba(0, 0, 0, 0.5);
}

.crm-live-avatar.small {
  height: 3.5rem;
  width: 3.5rem;
  border-radius: 1.1rem;
  font-size: 1rem;
}

.crm-live-stage-pill {
  padding: 0.18rem 0.55rem;
  font-size: 0.68rem;
  font-weight: 800;
}

.crm-live-detail-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.5rem;
  margin-bottom: 0.55rem;
}

.crm-live-detail-pill {
  min-width: 0;
  border-radius: 0.95rem;
  background: var(--crm-surface-2);
  padding: 0.5rem 0.6rem;
}

.crm-live-detail-pill p,
.crm-live-performance-item p {
  color: var(--crm-text-muted);
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.crm-live-detail-pill strong {
  display: block;
  overflow: hidden;
  margin-top: 0.2rem;
  color: var(--crm-text);
  font-size: 0.78rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.crm-live-soft-chip,
.crm-live-mini-chip {
  border: 1px solid var(--crm-border);
  background: var(--crm-surface-2);
  color: var(--crm-text-muted);
  font-size: 0.74rem;
  font-weight: 650;
}

.crm-live-soft-chip {
  padding: 0.38rem 0.62rem;
}

.crm-live-mini-chip {
  padding: 0.25rem 0.55rem;
}

.crm-live-warning {
  border: 1px solid color-mix(in srgb, var(--crm-warning) 34%, var(--crm-border));
  border-radius: 0.9rem;
  background: color-mix(in srgb, var(--crm-warning) 10%, var(--crm-surface));
  padding: 0.6rem 0.75rem;
  color: var(--crm-warning);
  font-size: 0.78rem;
  font-weight: 700;
}

.crm-live-controls {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  margin-top: 0.7rem;
}

.crm-live-control {
  display: inline-flex;
  min-height: 3rem;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  border: 1px solid var(--crm-border);
  border-radius: 1rem;
  background: var(--crm-surface-2);
  color: var(--crm-text);
  font-size: 0.68rem;
  font-weight: 800;
}

.crm-live-control.is-strong {
  border-color: color-mix(in srgb, var(--crm-success) 34%, var(--crm-border));
  color: var(--crm-success);
}

.crm-live-control.is-danger {
  border-color: color-mix(in srgb, var(--crm-danger) 32%, var(--crm-border));
  color: var(--crm-danger);
}

.crm-live-keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.45rem;
  margin-top: 0.85rem;
}

.crm-live-key {
  min-height: 2.4rem;
  border: 1px solid var(--crm-border);
  border-radius: 0.9rem;
  background: var(--crm-surface-2);
  color: var(--crm-text);
  font-weight: 850;
}

.crm-live-transfer {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.85rem;
}

.crm-live-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.crm-live-tab {
  border-radius: 999px;
  border: 1px solid transparent;
  padding: 0.38rem 0.65rem;
  color: var(--crm-text-muted);
  font-size: 0.74rem;
  font-weight: 750;
}

.crm-live-tab.is-active {
  border-color: color-mix(in srgb, var(--crm-accent) 26%, var(--crm-border));
  background: color-mix(in srgb, var(--crm-accent) 11%, var(--crm-surface));
  color: var(--crm-accent);
}

.crm-live-input,
.crm-live-select,
.crm-live-textarea,
.crm-live-filter-select {
  width: 100%;
  border: 1px solid var(--crm-border);
  border-radius: 0.95rem;
  background: var(--crm-surface-2);
  color: var(--crm-text);
  font-size: 0.84rem;
  outline: none;
}

.crm-live-input,
.crm-live-select,
.crm-live-filter-select {
  min-height: 2.4rem;
  padding: 0 0.75rem;
}

.crm-live-select,
.crm-live-filter-select {
  appearance: none;
  padding-right: 2rem;
}

.crm-live-filter-select {
  max-width: 9.5rem;
  font-size: 0.72rem;
}

.crm-live-textarea {
  min-height: 5.8rem;
  resize: vertical;
  padding: 0.85rem;
  line-height: 1.45;
}

.crm-live-feed-row,
.crm-live-queue-row,
.crm-live-snapshot-row,
.crm-live-icon-mini {
  border: 1px solid var(--crm-border);
  background: var(--crm-surface-2);
}

.crm-live-feed-row {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.75rem;
  border-radius: 1rem;
  padding: 0.65rem;
}

.crm-live-feed-icon {
  height: 2rem;
  width: 2rem;
  flex-shrink: 0;
  border-radius: 0.8rem;
  background: color-mix(in srgb, var(--crm-accent) 12%, var(--crm-surface));
  color: var(--crm-accent);
}

.crm-live-script-sections,
.crm-live-disposition-box,
.crm-live-snapshot-list {
  display: flex;
  flex-direction: column;
  gap: 0.65rem;
}

.crm-live-script-sections {
  margin-top: 0.65rem;
}

.crm-live-script-section {
  border-left: 3px solid var(--crm-accent);
