  -webkit-line-clamp: 3;
}

.crm-live-script-heading {
  margin-bottom: 0.35rem;
  color: var(--crm-accent);
  font-size: 0.72rem;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.crm-live-disposition-box {
