  border-top: 1px solid var(--crm-border);
  padding-top: 0.7rem;
}

.crm-live-card-footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.6rem;
  margin-top: 0.65rem;
  border-top: 1px solid var(--crm-border);
  padding-top: 0.55rem;
}

.crm-live-inline-link {
  color: var(--crm-accent);
  font-size: 0.78rem;
  font-weight: 800;
}

.crm-live-queue-row {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  gap: 0.75rem;
  border-radius: 1rem;
  padding: 0.72rem;
}

.crm-live-queue-status {
  margin-top: 0.25rem;
  border: 1px solid color-mix(in srgb, var(--crm-success) 28%, var(--crm-border));
  background: color-mix(in srgb, var(--crm-success) 10%, var(--crm-surface));
  padding: 0.16rem 0.45rem;
  color: var(--crm-success);
  font-size: 0.64rem;
  font-weight: 800;
