  --crm-surface-2: var(--panel-2);
  --crm-border: var(--border);
  --crm-text: var(--text);
  --crm-text-muted: var(--text-dim);
  background: var(--crm-bg) !important;
  color: var(--crm-text);
}

.ch-shell.crm-calls-workspace .ch-hero {
  padding: 20px 22px 0;
