  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.ch-shell.crm-calls-workspace .ch-filter-bar {
  margin: 0;
  padding: 14px;
  border: 1px solid var(--crm-border);
  border-radius: 1.25rem;
