/* Connect Chat 2026 side-panel redesign */
.cc-shell {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  gap: 18px;
  min-height: calc(100dvh - var(--topbar-height, 56px) - 28px);
  height: auto;
  max-height: none;
  padding: 0 0 28px;
  overflow: visible;
  background:
    radial-gradient(circle at 12% -8%, color-mix(in srgb, var(--accent) 18%, transparent), transparent 34%),
    radial-gradient(circle at 94% 2%, color-mix(in srgb, var(--accent-2) 13%, transparent), transparent 28%),
    transparent;
}

.cc-hero,
.cc-stats,
.cc-workspace,
.cc-stage-card {
  border: 1px solid color-mix(in srgb, var(--border) 82%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 94%, transparent), color-mix(in srgb, var(--panel-2) 82%, transparent)),
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--accent) 11%, transparent), transparent 32%);
  box-shadow: 0 20px 54px color-mix(in srgb, #000 18%, transparent);
  backdrop-filter: blur(16px);
}

.cc-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 22px;
  border-radius: 24px;
}

.cc-kicker {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.cc-hero h1 {
  margin: 9px 0 5px;
  font-size: clamp(32px, 4vw, 48px);
  line-height: 0.95;
  letter-spacing: -0.05em;
}

.cc-hero p,
.cc-stage-card p {
  max-width: 680px;
  margin: 0;
  color: var(--text-dim);
  font-size: 15px;
  line-height: 1.5;
}

.cc-primary-btn,
.cc-new-btn,
.cc-send-btn,
.cc-call-btn {
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #fff;
  font-weight: 850;
  cursor: pointer;
  box-shadow: 0 14px 30px color-mix(in srgb, var(--accent) 28%, transparent);
}

.cc-primary-btn {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 16px;
  white-space: nowrap;
}

.cc-new-btn {
  height: 34px;
  padding: 0 13px;
  font-size: 12px;
}

.cc-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  border-radius: 20px;
}

.cc-stats div {
  min-width: 0;
  padding: 16px;
  background: color-mix(in srgb, var(--panel) 58%, transparent);
}

.cc-stats span {
  display: block;
  color: var(--text-dim);
  font-size: 12px;
  font-weight: 800;
}

.cc-stats strong {
  display: block;
  margin-top: 6px;
  font-size: 28px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.cc-workspace {
  display: grid;
  grid-template-columns: minmax(320px, 440px) minmax(0, 1fr);
  min-height: min(680px, calc(100dvh - var(--topbar-height, 56px) - 230px));
  overflow: hidden;
  border-radius: 24px;
}

.cc-inbox {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-right: 1px solid color-mix(in srgb, var(--border) 80%, transparent);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 88%, transparent), color-mix(in srgb, var(--panel-2) 72%, transparent));
}

.cc-inbox-head {
  flex-shrink: 0;
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 18px;
  border-bottom: 1px solid color-mix(in srgb, var(--border) 68%, transparent);
}

.cc-inbox-head h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 850;
  letter-spacing: -0.02em;
}

.cc-inbox-head p {
  margin-top: 4px;
  color: var(--text-dim);
  font-size: 12px;
}

.cc-search,
.cc-people-search {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 14px 16px;
  min-height: 42px;
  padding: 0 13px;
  border: 1px solid color-mix(in srgb, var(--border) 86%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--panel-2) 86%, transparent);
  color: var(--text-dim);
  box-shadow: inset 0 1px 2px color-mix(in srgb, #000 10%, transparent);
}

.cc-search input,
.cc-people-search input {
  min-width: 0;
  flex: 1;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
  font-size: 13px;
}

.cc-thread-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0 12px 14px;
}

.cc-thread {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 12px;
  margin-bottom: 8px;
  border: 1px solid transparent;
  border-radius: 18px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  text-align: left;
  transition: transform 0.16s ease, border-color 0.16s ease, background 0.16s ease, box-shadow 0.16s ease;
}

.cc-thread:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--accent) 22%, var(--border));
  background: color-mix(in srgb, var(--panel) 72%, transparent);
  box-shadow: 0 14px 28px color-mix(in srgb, #000 10%, transparent);
}

.cc-thread.active {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--border));
  background:
    linear-gradient(135deg, color-mix(in srgb, var(--accent) 16%, var(--panel)), color-mix(in srgb, var(--accent-2) 8%, var(--panel-2)));
  box-shadow: 0 16px 34px color-mix(in srgb, var(--accent) 14%, transparent);
}

.cc-thread.pinned::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 14px;
  bottom: 14px;
  width: 3px;
  border-radius: 999px;
  background: linear-gradient(180deg, var(--accent), var(--accent-2));
}

.cc-avatar {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 13px;
  font-weight: 900;
  background: linear-gradient(135deg, #0ea5e9, var(--accent) 52%, var(--accent-2));
  box-shadow:
    0 10px 20px color-mix(in srgb, var(--accent) 20%, transparent),
    inset 0 1px 0 color-mix(in srgb, #fff 24%, transparent);
}

.cc-avatar.large {
  width: 44px;
  height: 44px;
  border-radius: 17px;
}

.cc-thread-main {
  flex: 1;
  min-width: 0;
}

.cc-thread-top,
.cc-thread-bottom {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.cc-thread-top {
  justify-content: space-between;
  margin-bottom: 5px;
}

.cc-thread-top strong,
.cc-thread-preview {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cc-thread-top strong {
  font-size: 13px;
  font-weight: 850;
}

.cc-thread-top small {
  flex-shrink: 0;
  color: var(--text-dim);
  font-size: 11px;
}

.cc-thread-preview {
  color: var(--text-dim);
  font-size: 12px;
}

.cc-channel-row {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}

.cc-channel,
.cc-sms-inbox-badge {
  flex-shrink: 0;
  border-radius: 999px;
  font-weight: 850;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.cc-channel {
  padding: 3px 7px;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  font-size: 10px;
}

.cc-channel-sms {
  color: var(--success);
  background: color-mix(in srgb, var(--success) 12%, transparent);
}

.cc-channel-tenant_group,
.cc-channel-group {
  color: var(--warning);
  background: color-mix(in srgb, var(--warning) 12%, transparent);
}

.cc-sms-inbox-badge {
  padding: 2px 6px;
  font-size: 9px;
}

.cc-sms-inbox-shared {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}

.cc-sms-inbox-personal {
  color: var(--text-dim);
  background: color-mix(in srgb, var(--text-dim) 12%, transparent);
}

.cc-thread-alert {
  color: var(--danger);
  flex-shrink: 0;
}

.cc-unread {
  min-width: 21px;
  height: 21px;
  padding: 0 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: 11px;
  font-weight: 900;
}

.cc-stage {
  min-width: 0;
  min-height: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at 18% 12%, color-mix(in srgb, var(--accent) 12%, transparent), transparent 30%),
    radial-gradient(circle at 84% 100%, color-mix(in srgb, var(--accent-2) 10%, transparent), transparent 34%),
    color-mix(in srgb, var(--bg) 74%, transparent);
}

.cc-stage-card {
  width: min(520px, 100%);
  padding: 28px;
  border-radius: 26px;
  text-align: left;
}

.cc-stage-icon {
  width: 58px;
  height: 58px;
  margin-bottom: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 22px;
  color: #fff;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  box-shadow: 0 18px 40px color-mix(in srgb, var(--accent) 26%, transparent);
}

.cc-stage-card h2 {
  margin: 8px 0 8px;
  font-size: clamp(24px, 3vw, 36px);
  line-height: 1;
  letter-spacing: -0.04em;
}

.cc-stage-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 18px;
}

.cc-stage-badges span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: color-mix(in srgb, var(--panel-2) 82%, transparent);
  color: var(--text-dim);
  font-size: 12px;
  font-weight: 800;
}

.cc-panel-backdrop {
  position: fixed;
  inset: var(--topbar-height, 56px) 0 0 0;
  z-index: 190;
  border: 0;
  background: color-mix(in srgb, #020617 42%, transparent);
  backdrop-filter: blur(4px);
  cursor: pointer;
}

.cc-side-panel {
  position: fixed;
  top: calc(var(--topbar-height, 56px) + 12px);
  right: 12px;
  bottom: 12px;
  z-index: 200;
  width: min(560px, calc(100vw - 24px));
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--border) 84%, transparent);
  border-radius: 28px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--panel) 96%, transparent), color-mix(in srgb, var(--panel-2) 88%, transparent)),
    radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 34%);
  box-shadow:
    -22px 0 70px color-mix(in srgb, #000 34%, transparent),
    inset 0 1px 0 color-mix(in srgb, #fff 10%, transparent);
  animation: cc-panel-in 180ms ease-out;
}

@keyframes cc-panel-in {
  from {
    opacity: 0;
    transform: translateX(28px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateX(0) scale(1);
  }
}

.cc-side-panel .cc-conversation {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background:
    radial-gradient(circle at 18% 0%, color-mix(in srgb, var(--accent) 9%, transparent), transparent 28%),
    color-mix(in srgb, var(--bg) 78%, transparent);
}

.cc-conversation.empty {
  display: none;
}

.cc-empty-chat {
  color: var(--text-dim);
  text-align: center;
}

.cc-empty-chat span {
  display: block;
  margin-bottom: 10px;
  font-size: 42px;
}

.cc-empty-chat h2 {
  margin-bottom: 5px;
  color: var(--text);
  font-size: 18px;
}

.cc-empty-mini {
  padding: 36px 18px;
  color: var(--text-dim);
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
  justify-content: center;
  font-size: 13px;
}

.cc-conv-head {
  position: sticky;
  top: 0;
  z-index: 12;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 72px;
  padding: 13px 16px;
  border-bottom: 1px solid color-mix(in srgb, var(--border) 76%, transparent);
  background: color-mix(in srgb, var(--panel) 94%, transparent);
  backdrop-filter: blur(18px);
}

.cc-conv-title {
  flex: 1;
  min-width: 0;
}

.cc-conv-title h2 {
  overflow: hidden;
  margin: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 16px;
  font-weight: 850;
}

.cc-conv-title p {
  margin-top: 3px;
  color: var(--text-dim);
  font-size: 12px;
}

.cc-icon-btn {
  border: 1px solid color-mix(in srgb, var(--border) 86%, transparent);
  border-radius: 14px;
  width: 38px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--panel-2) 88%, transparent);
  color: var(--text-dim);
  cursor: pointer;
  transition: transform 0.16s ease, border-color 0.16s ease, color 0.16s ease, background 0.16s ease;
}

.cc-icon-btn:hover {
  transform: translateY(-1px);
  color: var(--text);
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
  background: color-mix(in srgb, var(--accent) 10%, var(--panel-2));
}

.cc-panel-close {
  display: inline-flex;
}

.cc-call-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 38px;
  padding: 0 13px;
}

.cc-message-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding: 18px 18px 12px;
  scroll-behavior: auto;
}

.cc-msg-row {
  display: flex;
  margin-bottom: 13px;
}

.cc-msg-row.mine {
  justify-content: flex-end;
}

.cc-msg-row.theirs {
  justify-content: flex-start;
}

.cc-msg-wrap {
  max-width: min(78%, 430px);
  position: relative;
}

.cc-msg-sender {
  margin: 0 0 4px 8px;
  color: var(--text-dim);
  font-size: 11px;
}

.cc-bubble {
  position: relative;
  padding: 10px 12px;
  border-radius: 18px;
  font-size: 13px;
  line-height: 1.45;
  word-break: break-word;
  box-shadow: 0 10px 24px color-mix(in srgb, #000 12%, transparent);
}

.cc-bubble.mine {
  color: #fff;
  background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 92%, #38bdf8), var(--accent));
  border-bottom-right-radius: 7px;
}

.cc-bubble.theirs {
  color: var(--text);
  border: 1px solid color-mix(in srgb, var(--border) 78%, transparent);
  background: color-mix(in srgb, var(--panel) 92%, transparent);
  border-bottom-left-radius: 7px;
}

.cc-bubble.deleted {
  color: var(--text-dim);
  font-style: italic;
  background: color-mix(in srgb, var(--panel-2) 80%, transparent);
}

.cc-msg-body {
  white-space: pre-wrap;
}

.cc-msg-link {
  color: inherit;
  font-weight: 800;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.cc-composer {
  position: sticky;
  bottom: 0;
  z-index: 12;
  flex-shrink: 0;
  padding: 12px 14px 14px;
  border-top: 1px solid color-mix(in srgb, var(--border) 74%, transparent);
  background: color-mix(in srgb, var(--panel) 95%, transparent);
  backdrop-filter: blur(18px);
}

.cc-compose-row {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}

.cc-compose-row textarea {
  flex: 1;
  min-width: 0;
  min-height: 40px;
  max-height: 120px;
  resize: none;
  padding: 11px 13px;
  border-radius: 20px;
  border: 1px solid color-mix(in srgb, var(--border) 86%, transparent);
  outline: none;
  background: color-mix(in srgb, var(--panel-2) 88%, transparent);
  color: var(--text);
  font: inherit;
  font-size: 13px;
}

.cc-send-btn {
  width: 40px;
  height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.cc-primary-btn:disabled,
.cc-send-btn:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.cc-composer-disabled {
  padding: 14px 16px;
  border-top: 1px solid var(--border);
  background: color-mix(in srgb, var(--panel) 92%, transparent);
}

.cc-composer-disabled p {
  margin: 0;
  color: var(--text-dim);
  font-size: 12px;
  line-height: 1.4;
}

.cc-composer-reply,
.cc-pending,
.cc-recording {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.cc-composer-reply {
  justify-content: space-between;
  border-left: 3px solid var(--accent);
  border-radius: 14px;
  background: color-mix(in srgb, var(--panel-2) 88%, transparent);
  padding: 8px 10px;
  color: var(--text-dim);
  font-size: 12px;
}

.cc-composer-reply button,
.cc-pending-chip button,
.cc-recording button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.cc-pending-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--panel-2) 88%, transparent);
  border: 1px solid var(--border);
  font-size: 12px;
}

.cc-pending-chip small,
.cc-sms-counter {
  color: var(--text-dim);
}

.cc-sms-counter {
  margin-top: 6px;
  padding: 0 2px;
  font-size: 11px;
  line-height: 1.35;
}

.cc-record-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--danger);
  animation: presence-pulse 1.2s ease-in-out infinite;
}

.cc-toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 260;
  padding: 11px 15px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--border));
  background: var(--panel);
  color: var(--text);
  box-shadow: var(--shadow);
}

:root[data-theme="light"] .cc-hero,
:root[data-theme="light"] .cc-stats,
:root[data-theme="light"] .cc-workspace,
:root[data-theme="light"] .cc-stage-card,
:root[data-theme="light"] .cc-side-panel {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(244, 249, 255, 0.92)),
    radial-gradient(circle at 100% 0%, rgba(211, 229, 255, 0.64), transparent 36%);
  border-color: rgba(194, 211, 231, 0.92);
  box-shadow:
    0 20px 52px rgba(31, 53, 78, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.86);
}

:root[data-theme="light"] .cc-shell {
  background:
    radial-gradient(circle at 16% -8%, rgba(85, 169, 255, 0.16), transparent 32%),
    radial-gradient(circle at 96% 2%, rgba(101, 116, 255, 0.1), transparent 28%),
    transparent;
}

:root[data-theme="light"] .cc-inbox,
:root[data-theme="light"] .cc-conv-head,
:root[data-theme="light"] .cc-composer {
  background: rgba(255, 255, 255, 0.82);
}

:root[data-theme="light"] .cc-stage {
  background:
    radial-gradient(circle at 18% 12%, rgba(31, 127, 216, 0.12), transparent 30%),
    linear-gradient(180deg, rgba(248, 251, 255, 0.72), rgba(237, 244, 251, 0.9));
}

@media (max-width: 1120px) {
  .cc-workspace {
    grid-template-columns: 1fr;
  }

  .cc-inbox {
    border-right: 0;
    border-bottom: 1px solid var(--border);
    max-height: 560px;
  }

  .cc-stage {
    min-height: 300px;
  }
}

@media (max-width: 760px) {
  .cc-hero {
    flex-direction: column;
    padding: 18px;
  }

  .cc-primary-btn {
    width: 100%;
  }

  .cc-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cc-workspace {
    min-height: auto;
  }

  .cc-stage {
    display: none;
  }

  .cc-side-panel {
    inset: var(--topbar-height, 56px) 0 0 0;
    width: auto;
    border-radius: 0;
  }

  .cc-panel-backdrop {
    display: none;
  }

  .cc-msg-wrap {
    max-width: 88%;
  }

  .cc-call-btn {
    width: 38px;
    padding: 0;
    justify-content: center;
  }

  .cc-call-btn span {
    display: none;
  }

  .cc-compose-row {
    gap: 6px;
  }

  .cc-compose-row .cc-icon-btn:nth-of-type(2),
  .cc-compose-row .cc-icon-btn:nth-of-type(4) {
    display: none;
  }
}

@media (max-width: 560px) {
  .cc-stats {
    grid-template-columns: 1fr;
  }

  .cc-inbox-head {
    flex-direction: column;
  }

  .cc-new-btn {
    width: 100%;
  }
}

/* Chat alignment pass: use the same compact CRM workspace rhythm as the other pages. */
.cc-shell.crm-queue-workspace {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
  height: auto;
  max-height: none;
  padding: 0 0 18px;
  overflow: visible;
  background: var(--crm-bg, transparent);
  color: var(--crm-text, var(--text));
}

.cc-page-header {
  display: block;
  padding: 0;
}

.cc-page-header .contacts-header-panel {
  width: 100%;
}

.cc-header-action {
  min-height: 2.35rem;
  border-radius: 999px;
}

.cc-kpi-strip {
  margin: 0;
}

.cc-workspace {
  display: grid;
  grid-template-columns: minmax(320px, 420px) minmax(0, 1fr);
  min-height: min(640px, calc(100dvh - var(--topbar-height, 56px) - 235px));
  overflow: hidden;
  border: 1px solid var(--crm-border, var(--border));
  border-radius: var(--radius-lg, 1.25rem);
  background: var(--crm-surface, var(--panel));
  box-shadow: var(--crm-shadow, 0 12px 32px color-mix(in srgb, #000 18%, transparent));
  backdrop-filter: none;
}

.cc-workspace,
.cc-inbox,
.cc-stage {
  background-image: none;
}

.cc-inbox {
  border-right: 1px solid color-mix(in srgb, var(--crm-border, var(--border)) 82%, transparent);
  background: var(--crm-surface, var(--panel));
}

.cc-inbox-head {
  padding: 14px 16px;
  border-bottom: 1px solid color-mix(in srgb, var(--crm-border, var(--border)) 74%, transparent);
  background: color-mix(in srgb, var(--crm-surface-2, var(--panel-2)) 44%, transparent);
}

.cc-inbox-head h2 {
  color: var(--crm-text, var(--text));
  font-size: 15px;
  font-weight: 750;
  letter-spacing: -0.01em;
}

.cc-inbox-head p {
  color: var(--crm-text-muted, var(--text-dim));
  font-size: 11px;
}

.cc-new-btn {
  height: 30px;
  padding: 0 10px;
  border-radius: var(--radius-sm, 0.75rem);
  font-size: 11px;
  box-shadow: none;
}

.cc-search {
  margin: 12px;
  min-height: 38px;
  border-radius: var(--radius-sm, 0.75rem);
  border-color: color-mix(in srgb, var(--crm-border, var(--border)) 80%, transparent);
  background: var(--crm-surface-2, var(--panel-2));
  box-shadow: none;
}

.cc-thread-list {
  padding: 0 8px 10px;
}

.cc-thread {
  margin-bottom: 6px;
  padding: 10px;
  border-radius: var(--radius-sm, 0.75rem);
  background: color-mix(in srgb, var(--crm-surface-2, var(--panel-2)) 36%, transparent);
}

.cc-thread:hover {
  transform: none;
  border-color: color-mix(in srgb, var(--crm-border, var(--border)) 96%, transparent);
  background: color-mix(in srgb, var(--crm-surface-2, var(--panel-2)) 76%, transparent);
  box-shadow: none;
}

.cc-thread.active {
  border-color: color-mix(in srgb, var(--crm-accent, var(--accent)) 42%, var(--crm-border, var(--border)));
  background: color-mix(in srgb, var(--crm-accent, var(--accent)) 10%, var(--crm-surface-2, var(--panel-2)));
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 5%, transparent);
}

.cc-avatar {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm, 0.75rem);
  box-shadow: inset 0 1px 0 color-mix(in srgb, #fff 18%, transparent);
}

.cc-thread-top strong {
  color: var(--crm-text, var(--text));
  font-size: 12px;
}

.cc-thread-preview,
.cc-thread-top small,
.cc-empty-mini,
.cc-stage-empty span {
  color: var(--crm-text-muted, var(--text-dim));
}

.cc-channel,
.cc-sms-inbox-badge {
  font-size: 9px;
}

.cc-stage {
  min-height: 0;
  display: grid;
  place-items: center;
  padding: 18px;
  background: color-mix(in srgb, var(--crm-surface-2, var(--panel-2)) 32%, transparent);
}

.cc-stage-empty {
  display: flex;
  max-width: 24rem;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 28px;
  color: var(--crm-text-muted, var(--text-dim));
  text-align: center;
}

.cc-stage-empty svg {
  color: var(--crm-accent, var(--accent));
}

.cc-stage-empty strong {
  color: var(--crm-text, var(--text));
  font-size: 16px;
  font-weight: 650;
}

.cc-stage-empty span {
  font-size: 13px;
  line-height: 1.45;
}

.cc-panel-backdrop {
  background: color-mix(in srgb, #020617 34%, transparent);
  backdrop-filter: blur(2px);
}

.cc-side-panel {
  top: calc(var(--topbar-height, 56px) + 10px);
  right: 10px;
